-- Training room: typical wines, batch 1 (spec
-- docs/superpowers/specs/2026-09-25-training-room-design.md §4.7, D21).
-- GENERATED from data/training/archetypes-batch-1.json by scripts/training/gen-archetype-batch-migration.mjs
-- on 2026-09-26. Edit the JSON and regenerate; never edit this file by hand.
--
-- 87 archetypes, 881 aroma links (133 signature),
-- 34 designation links, 69 map placements.
-- Every country, region, appellation, grape, designation, aroma term and map
-- place is resolved by its exact live name inside its parent; anything but
-- exactly one row raises. A name already in wine_archetypes is skipped with
-- all its links, so applying this twice is a no-op.
--
-- Reference rows added: none (missingReferenceRows is empty).
--
-- Requires 20260925120000_training_room.sql. No begin/commit: the applier
-- owns the transaction.

set local lock_timeout = '10s';
-- A second apply inside one transaction (the DB suite's idempotency test)
-- would otherwise meet the temp tables of the first.
drop table if exists pg_temp._batch_archetypes, pg_temp._batch_aromas, pg_temp._batch_designations,
  pg_temp._batch_resolved, pg_temp._batch_new;

do $$
begin
  if to_regclass('public.wine_archetype_designations') is null
     or not exists (select 1 from information_schema.columns
                    where table_schema = 'public' and table_name = 'wine_archetype_aromas'
                      and column_name = 'signature')
     or not exists (select 1 from information_schema.columns
                    where table_schema = 'public' and table_name = 'wine_archetypes'
                      and column_name = 'appellation_id') then
    raise exception 'apply 20260925120000_training_room.sql first';
  end if;
end $$;

create temp table _batch_archetypes (
  ord int primary key,
  name text not null unique,
  country text not null, region text not null, appellation text not null,
  place_key text,
  colour wine_colour not null, style wine_style not null,
  primary_grape text not null, secondary_grape text,
  typical_age_low smallint, typical_age_high smallint,
  quality_low smallint not null, quality_high smallint not null,
  sat jsonb not null,
  description text not null
) on commit drop;

create temp table _batch_aromas (
  name text not null, kind text not null, group_name text not null, term text not null,
  signature boolean not null,
  primary key (name, kind, group_name, term)
) on commit drop;

create temp table _batch_designations (
  name text not null, designation text not null,
  primary key (name, designation)
) on commit drop;

-- Every name, resolved inside its parent: one array per reference, which the
-- assert below needs to hold exactly one element.
create temp table _batch_resolved on commit drop as
select b.ord, b.name,
       array(select c.id from public.countries c where c.name = b.country) as country_ids,
       array(select r.id from public.regions r join public.countries c on c.id = r.country_id
              where c.name = b.country and r.name = b.region) as region_ids,
       array(select a.id from public.appellations a
               join public.regions r on r.id = a.region_id
               join public.countries c on c.id = r.country_id
              where c.name = b.country and r.name = b.region and a.name = b.appellation) as appellation_ids,
       array(select g.id from public.grapes g where g.name = b.primary_grape) as primary_grape_ids,
       case when b.secondary_grape is null then array[null::uuid]
            else array(select g.id from public.grapes g where g.name = b.secondary_grape) end as secondary_grape_ids,
       case when b.place_key is null then array[null::uuid]
            else array(select p.id from public.wine_places p where p.canonical_key = b.place_key) end as place_ids
  from _batch_archetypes b;

do $$
declare
  v_text text;
begin
  if (select count(*) from _batch_archetypes) <> 87
     or (select count(*) from _batch_aromas) <> 881
     or (select count(*) from _batch_aromas where signature) <> 133
     or (select count(*) from _batch_designations) <> 34 then
    raise exception 'the batch rows did not load in full';
  end if;
  select string_agg(format('%s: %s resolves to %s rows', r.name, x.field, x.n), '; ' order by r.ord, x.field)
    into v_text
  from _batch_resolved r
  cross join lateral (values ('country', cardinality(r.country_ids)),
                             ('region', cardinality(r.region_ids)),
                             ('appellation', cardinality(r.appellation_ids)),
                             ('primary grape', cardinality(r.primary_grape_ids)),
                             ('secondary grape', cardinality(r.secondary_grape_ids)),
                             ('map place', cardinality(r.place_ids))) as x (field, n)
  where x.n <> 1;
  if v_text is not null then
    raise exception 'a batch reference does not resolve to exactly one live row: %', v_text;
  end if;
  select string_agg(format('%s: %s (%s) resolves to %s terms', x.name, x.term, x.group_name, x.n), '; ')
    into v_text
  from (select a.name, a.term, a.group_name,
               (select count(*) from public.wset_aroma_terms t
                 where t.group_name = a.group_name and t.term = a.term) as n
          from _batch_aromas a) x
  where x.n <> 1;
  if v_text is not null then
    raise exception 'an aroma term does not resolve to exactly one live row: %', v_text;
  end if;
  select string_agg(format('%s: %s', d.name, d.designation), '; ') into v_text
  from _batch_designations d
  where (select count(*) from public.type_designations td
          where td.name = d.designation and td.is_active) <> 1;
  if v_text is not null then
    raise exception 'a designation does not resolve to exactly one active row: %', v_text;
  end if;
end $$;

create temp table _batch_new (id uuid primary key, name text not null unique) on commit drop;

with inserted as (
    name, wine_place_id, country_id, region_id, appellation_id, colour, style,
    primary_grape_id, secondary_grape_id, description, sat, quality_low, quality_high,
    typical_age_low, typical_age_high, sort_order
  )
  select b.name, r.place_ids[1], r.country_ids[1], r.region_ids[1], r.appellation_ids[1],
         b.colour, b.style, r.primary_grape_ids[1], r.secondary_grape_ids[1], b.description,
         b.sat, b.quality_low, b.quality_high, b.typical_age_low, b.typical_age_high,
         (select coalesce(max(a.sort_order), 0) from public.wine_archetypes a) + b.ord
    from _batch_archetypes b
    join _batch_resolved r on r.ord = b.ord
   where not exists (select 1 from public.wine_archetypes a where a.name = b.name)
  returning id, name
)

select n.id, t.id, x.kind, x.signature
  from _batch_aromas x
  join _batch_new n on n.name = x.name
  join public.wset_aroma_terms t on t.group_name = x.group_name and t.term = x.term;

select n.id, td.id
  from _batch_designations d
  join _batch_new n on n.name = d.name
  join public.type_designations td on td.name = d.designation and td.is_active;

-- An archetype with a map place shows there, like the live ones
-- (20260829224000's back-fill: its home place, its own sort_order).
select a.id, a.wine_place_id, a.sort_order
  from _batch_new n
  join public.wine_archetypes a on a.id = n.id
 where a.wine_place_id is not null
on conflict (archetype_id, wine_place_id) do nothing;

-- Post-state, same transaction.
do $$
declare
  v_new int;
  v_text text;
begin
  -- Every batch name is in wine_archetypes exactly once.
  select string_agg(format('%s x%s', b.name, coalesce(x.n, 0)), '; ') into v_text
  from _batch_archetypes b
  left join (select a.name, count(*) as n from public.wine_archetypes a group by a.name) x on x.name = b.name
  where coalesce(x.n, 0) <> 1;
  if v_text is not null then
    raise exception 'batch archetypes are not each present exactly once: %', v_text;
  end if;
  -- The rows THIS run wrote carry every link the file lists.
  select count(*) into v_new from _batch_new;
  select string_agg(n.name, '; ') into v_text
  from _batch_new n
  join public.wine_archetypes a on a.id = n.id
  where (select count(*) from public.wine_archetype_aromas l where l.archetype_id = n.id)
          <> (select count(*) from _batch_aromas x where x.name = n.name)
     or (select count(*) from public.wine_archetype_aromas l where l.archetype_id = n.id and l.signature)
          <> (select count(*) from _batch_aromas x where x.name = n.name and x.signature)
     or (select count(*) from public.wine_archetype_designations l where l.archetype_id = n.id)
          <> (select count(*) from _batch_designations x where x.name = n.name)
     or (select count(*) from public.wine_archetype_placements p where p.archetype_id = n.id)
          <> case when a.wine_place_id is null then 0 else 1 end;
  if v_text is not null then
    raise exception 'batch archetypes written without every link: %', v_text;
  end if;
  raise notice 'archetypes batch 1: % new of 87; wine_archetypes now %',
    v_new, (select count(*) from public.wine_archetypes);
end $$;
