insert into _batch_archetypes values
  (1, 'A typical Pauillac', 'France', 'Bordeaux', 'Pauillac AOC', 'france.bordeaux.haut-medoc.pauillac', 'RED'::wine_colour, 'STILL'::wine_style, 'Cabernet Sauvignon', 'Merlot', 8, 30, 89, 98, '{"appearanceIntensity":["MEDIUM_PLUS","DEEP"],"colourHue":["RUBY","GARNET"],"noseIntensity":["MEDIUM_PLUS","PRONOUNCED"],"development":["DEVELOPING","FULLY_DEVELOPED"],"sweetness":["DRY","DRY"],"acidity":["MEDIUM","MEDIUM_PLUS"],"tannin":["MEDIUM_PLUS","HIGH"],"alcohol":["MEDIUM","HIGH"],"body":["MEDIUM_PLUS","FULL"],"flavourIntensity":["MEDIUM_PLUS","PRONOUNCED"],"finish":["MEDIUM_PLUS","LONG"]}'::jsonb, 'Cabernet-led Médoc blend from deep gravel: cassis, cedar and pencil-shaving oak over firm, fine-grained tannin and a long, dry finish. Deeper and more austere than Margaux and slow to open; tobacco and leather appear with bottle age.'),
  (2, 'A typical Saint-Julien', 'France', 'Bordeaux', 'Saint-Julien AOC', 'france.bordeaux.haut-medoc.saint-julien', 'RED'::wine_colour, 'STILL'::wine_style, 'Cabernet Sauvignon', 'Merlot', 8, 25, 88, 96, '{"appearanceIntensity":["MEDIUM","DEEP"],"colourHue":["RUBY","GARNET"],"noseIntensity":["MEDIUM","MEDIUM_PLUS"],"development":["DEVELOPING","FULLY_DEVELOPED"],"sweetness":["DRY","DRY"],"acidity":["MEDIUM","MEDIUM_PLUS"],"tannin":["MEDIUM_PLUS","HIGH"],"alcohol":["MEDIUM","HIGH"],"body":["MEDIUM_PLUS","FULL"],"flavourIntensity":["MEDIUM_PLUS","PRONOUNCED"],"finish":["MEDIUM_PLUS","LONG"]}'::jsonb, 'Cabernet-led Médoc between Pauillac''s power and Margaux''s perfume: cassis and cedar over polished, firm tannin, the fruit sitting evenly through a long finish. Cigar-box and leather notes arrive after about a decade.'),
  (3, 'A typical Saint-Estèphe', 'France', 'Bordeaux', 'Saint-Estèphe AOC', 'france.bordeaux.haut-medoc.saint-estephe', 'RED'::wine_colour, 'STILL'::wine_style, 'Cabernet Sauvignon', 'Merlot', 10, 30, 86, 95, '{"appearanceIntensity":["MEDIUM_PLUS","DEEP"],"colourHue":["RUBY","GARNET"],"noseIntensity":["MEDIUM","MEDIUM_PLUS"],"development":["DEVELOPING","FULLY_DEVELOPED"],"sweetness":["DRY","DRY"],"acidity":["MEDIUM_PLUS","HIGH"],"tannin":["MEDIUM_PLUS","HIGH"],"alcohol":["MEDIUM","HIGH"],"body":["MEDIUM_PLUS","FULL"],"flavourIntensity":["MEDIUM","MEDIUM_PLUS"],"finish":["MEDIUM_PLUS","LONG"]}'::jsonb, 'The Médoc''s firmest commune: clay soils and more Merlot give dark plum and cassis with earthy, almost rustic tannin and fresh acidity. Closed and austere when young, it needs longer in bottle than its neighbours.'),
  (4, 'A typical Pessac-Léognan red', 'France', 'Bordeaux', 'Pessac-Léognan AOC', 'france.bordeaux.pessac-leognan', 'RED'::wine_colour, 'STILL'::wine_style, 'Cabernet Sauvignon', 'Merlot', 6, 25, 86, 96, '{"appearanceIntensity":["MEDIUM","DEEP"],"colourHue":["RUBY","GARNET"],"noseIntensity":["MEDIUM","MEDIUM_PLUS"],"development":["DEVELOPING","FULLY_DEVELOPED"],"sweetness":["DRY","DRY"],"acidity":["MEDIUM","MEDIUM_PLUS"],"tannin":["MEDIUM","MEDIUM_PLUS"],"alcohol":["MEDIUM","HIGH"],"body":["MEDIUM","MEDIUM_PLUS"],"flavourIntensity":["MEDIUM","MEDIUM_PLUS"],"finish":["MEDIUM_PLUS","LONG"]}'::jsonb, 'Graves Cabernet–Merlot from warm gravel south of the city: cassis and red plum with a smoky, earthy, tobacco-leaf edge that sets it apart from the Médoc. Body and tannin are medium to medium(+), a little softer and more savoury than Pauillac.'),
  (5, 'A typical Pessac-Léognan white', 'France', 'Bordeaux', 'Pessac-Léognan AOC', 'france.bordeaux.pessac-leognan', 'WHITE'::wine_colour, 'STILL'::wine_style, 'Sauvignon Blanc', 'Semillon', 3, 15, 87, 95, '{"appearanceIntensity":["PALE","MEDIUM"],"colourHue":["LEMON","GOLD"],"noseIntensity":["MEDIUM_PLUS","PRONOUNCED"],"development":["YOUTHFUL","DEVELOPING"],"sweetness":["DRY","DRY"],"acidity":["MEDIUM_PLUS","HIGH"],"tannin":["LOW","LOW"],"alcohol":["MEDIUM","MEDIUM"],"body":["MEDIUM","MEDIUM_PLUS"],"flavourIntensity":["MEDIUM_PLUS","PRONOUNCED"],"finish":["MEDIUM_PLUS","LONG"]}'::jsonb, 'Barrel-fermented Sauvignon Blanc and Semillon: grapefruit and cut grass from the Sauvignon, a waxy, broader texture from the Semillon, and vanilla and toast from new oak over high acidity. Honey and nutty notes come after five to ten years.'),
  (6, 'A typical Saint-Émilion', 'France', 'Bordeaux', 'Saint-Émilion Grand Cru AOC', 'france.bordeaux.saint-emilion.saint-emilion-grand-cru', 'RED'::wine_colour, 'STILL'::wine_style, 'Merlot', 'Cabernet Franc', 6, 20, 86, 96, '{"appearanceIntensity":["MEDIUM","DEEP"],"colourHue":["RUBY","GARNET"],"noseIntensity":["MEDIUM","MEDIUM_PLUS"],"development":["DEVELOPING","FULLY_DEVELOPED"],"sweetness":["DRY","DRY"],"acidity":["MEDIUM","MEDIUM_PLUS"],"tannin":["MEDIUM_PLUS","HIGH"],"alcohol":["MEDIUM","HIGH"],"body":["MEDIUM_PLUS","FULL"],"flavourIntensity":["MEDIUM_PLUS","PRONOUNCED"],"finish":["MEDIUM_PLUS","LONG"]}'::jsonb, 'Merlot with Cabernet Franc from limestone and clay: plum and black cherry with mocha and sweet vanilla oak, riper and rounder than the Médoc but with a firm, chalky grip. Cabernet Franc adds a leafy, tobacco lift.'),
  (7, 'A typical Pomerol', 'France', 'Bordeaux', 'Pomerol AOC', 'france.bordeaux.pomerol', 'RED'::wine_colour, 'STILL'::wine_style, 'Merlot', 'Cabernet Franc', 6, 20, 87, 97, '{"appearanceIntensity":["MEDIUM_PLUS","DEEP"],"colourHue":["RUBY","GARNET"],"noseIntensity":["MEDIUM_PLUS","PRONOUNCED"],"development":["DEVELOPING","FULLY_DEVELOPED"],"sweetness":["DRY","DRY"],"acidity":["MEDIUM","MEDIUM_PLUS"],"tannin":["MEDIUM","MEDIUM_PLUS"],"alcohol":["MEDIUM","HIGH"],"body":["MEDIUM_PLUS","FULL"],"flavourIntensity":["MEDIUM_PLUS","PRONOUNCED"],"finish":["MEDIUM_PLUS","LONG"]}'::jsonb, 'Merlot-dominant wine from clay over an iron-rich subsoil: plush plum and black cherry, mocha and a truffly, earthy note, full body and velvety rather than firm tannin. The roundest texture in Bordeaux at a similar acidity.'),
  (8, 'A typical Gevrey-Chambertin', 'France', 'Bourgogne', 'Gevrey-Chambertin AOC', 'france.bourgogne.cote-de-nuits.gevrey-chambertin', 'RED'::wine_colour, 'STILL'::wine_style, 'Pinot Noir', null, 4, 15, 87, 96, '{"appearanceIntensity":["MEDIUM_MINUS","MEDIUM"],"colourHue":["RUBY","GARNET"],"noseIntensity":["MEDIUM_PLUS","PRONOUNCED"],"development":["YOUTHFUL","DEVELOPING"],"sweetness":["DRY","DRY"],"acidity":["MEDIUM_PLUS","HIGH"],"tannin":["MEDIUM","MEDIUM_PLUS"],"alcohol":["MEDIUM","MEDIUM"],"body":["MEDIUM","MEDIUM_PLUS"],"flavourIntensity":["MEDIUM_PLUS","PRONOUNCED"],"finish":["MEDIUM_PLUS","LONG"]}'::jsonb, 'The most muscular Côte de Nuits village: dark cherry and blackberry fruit with earthy, meaty and gamey notes, more tannin and body than Chambolle, over the high acidity of all Côte d''Or Pinot. Savoury, forest-floor character builds from about eight years.'),
  (9, 'A typical Chambolle-Musigny', 'France', 'Bourgogne', 'Chambolle-Musigny AOC', 'france.bourgogne.cote-de-nuits.chambolle-musigny', 'RED'::wine_colour, 'STILL'::wine_style, 'Pinot Noir', null, 4, 15, 88, 96, '{"appearanceIntensity":["PALE","MEDIUM"],"colourHue":["RUBY","GARNET"],"noseIntensity":["MEDIUM_PLUS","PRONOUNCED"],"development":["YOUTHFUL","DEVELOPING"],"sweetness":["DRY","DRY"],"acidity":["MEDIUM_PLUS","HIGH"],"tannin":["MEDIUM_MINUS","MEDIUM"],"alcohol":["MEDIUM","MEDIUM"],"body":["MEDIUM_MINUS","MEDIUM"],"flavourIntensity":["MEDIUM_PLUS","PRONOUNCED"],"finish":["MEDIUM_PLUS","LONG"]}'::jsonb, 'The most perfumed Côte de Nuits village: raspberry and red cherry with violet and rose, light-to-medium body and fine, low-to-medium tannin carried by high acidity. Paler and lighter in structure than Gevrey or Nuits-Saint-Georges.'),
  (10, 'A typical Nuits-Saint-Georges', 'France', 'Bourgogne', 'Nuits-Saint-Georges AOC', 'france.bourgogne.cote-de-nuits.nuits-saint-georges', 'RED'::wine_colour, 'STILL'::wine_style, 'Pinot Noir', null, 5, 18, 86, 95, '{"appearanceIntensity":["MEDIUM_MINUS","MEDIUM"],"colourHue":["RUBY","GARNET"],"noseIntensity":["MEDIUM","MEDIUM_PLUS"],"development":["YOUTHFUL","DEVELOPING"],"sweetness":["DRY","DRY"],"acidity":["MEDIUM_PLUS","HIGH"],"tannin":["MEDIUM","MEDIUM_PLUS"],"alcohol":["MEDIUM","MEDIUM"],"body":["MEDIUM","MEDIUM_PLUS"],"flavourIntensity":["MEDIUM","MEDIUM_PLUS"],"finish":["MEDIUM_PLUS","LONG"]}'::jsonb, 'Firm, earthy Pinot Noir from the southern end of the Côte de Nuits: black cherry and plum with forest floor and leather, sturdier tannin than Vosne or Chambolle and a slightly rustic grip. Less perfume, more structure.'),
  (11, 'A typical Pommard', 'France', 'Bourgogne', 'Pommard AOC', 'france.bourgogne.cote-de-beaune.pommard', 'RED'::wine_colour, 'STILL'::wine_style, 'Pinot Noir', null, 5, 18, 85, 94, '{"appearanceIntensity":["MEDIUM","MEDIUM_PLUS"],"colourHue":["RUBY","GARNET"],"noseIntensity":["MEDIUM","MEDIUM_PLUS"],"development":["YOUTHFUL","DEVELOPING"],"sweetness":["DRY","DRY"],"acidity":["MEDIUM_PLUS","HIGH"],"tannin":["MEDIUM_PLUS","HIGH"],"alcohol":["MEDIUM","MEDIUM"],"body":["MEDIUM","MEDIUM_PLUS"],"flavourIntensity":["MEDIUM","MEDIUM_PLUS"],"finish":["MEDIUM","MEDIUM_PLUS"]}'::jsonb, 'The sturdiest Côte de Beaune red: dark cherry and plum with earthy, iron-like and meaty notes, firmer tannin and more body than neighbouring Volnay. Often closed for its first five years.'),
  (12, 'A typical Volnay', 'France', 'Bourgogne', 'Volnay AOC', 'france.bourgogne.cote-de-beaune.volnay', 'RED'::wine_colour, 'STILL'::wine_style, 'Pinot Noir', null, 4, 15, 86, 95, '{"appearanceIntensity":["PALE","MEDIUM"],"colourHue":["RUBY","GARNET"],"noseIntensity":["MEDIUM_PLUS","PRONOUNCED"],"development":["YOUTHFUL","DEVELOPING"],"sweetness":["DRY","DRY"],"acidity":["MEDIUM_PLUS","HIGH"],"tannin":["MEDIUM_MINUS","MEDIUM"],"alcohol":["MEDIUM","MEDIUM"],"body":["MEDIUM_MINUS","MEDIUM"],"flavourIntensity":["MEDIUM","MEDIUM_PLUS"],"finish":["MEDIUM_PLUS","LONG"]}'::jsonb, 'The Côte de Beaune''s most delicate red: red cherry, raspberry and violet on a light-to-medium frame with silky, low tannin and high acidity. Close to Chambolle in style, with a little less depth.'),
  (13, 'A typical Corton', 'France', 'Bourgogne', 'Corton AOC', 'france.bourgogne.cote-de-beaune.aloxe-corton.corton', 'RED'::wine_colour, 'STILL'::wine_style, 'Pinot Noir', null, 8, 25, 89, 96, '{"appearanceIntensity":["MEDIUM","MEDIUM_PLUS"],"colourHue":["RUBY","GARNET"],"noseIntensity":["MEDIUM_PLUS","PRONOUNCED"],"development":["DEVELOPING","FULLY_DEVELOPED"],"sweetness":["DRY","DRY"],"acidity":["MEDIUM_PLUS","HIGH"],"tannin":["MEDIUM_PLUS","HIGH"],"alcohol":["MEDIUM","MEDIUM"],"body":["MEDIUM","MEDIUM_PLUS"],"flavourIntensity":["MEDIUM_PLUS","PRONOUNCED"],"finish":["MEDIUM_PLUS","LONG"]}'::jsonb, 'The Côte de Beaune''s only red grand cru: dark cherry and plum with earthy, iron-edged tannin, firmer and more closed than most Beaune reds. It needs eight years or more to show forest floor and leather.'),
  (14, 'A typical Corton-Charlemagne', 'France', 'Bourgogne', 'Corton-Charlemagne AOC', 'france.bourgogne.cote-de-beaune.aloxe-corton.corton-charlemagne', 'WHITE'::wine_colour, 'STILL'::wine_style, 'Chardonnay', null, 6, 20, 91, 97, '{"appearanceIntensity":["PALE","MEDIUM"],"colourHue":["LEMON","GOLD"],"noseIntensity":["MEDIUM_PLUS","PRONOUNCED"],"development":["YOUTHFUL","DEVELOPING"],"sweetness":["DRY","DRY"],"acidity":["MEDIUM_PLUS","HIGH"],"tannin":["LOW","LOW"],"alcohol":["MEDIUM","HIGH"],"body":["MEDIUM_PLUS","FULL"],"flavourIntensity":["MEDIUM_PLUS","PRONOUNCED"],"finish":["MEDIUM_PLUS","LONG"]}'::jsonb, 'Grand cru Chardonnay from the hill of Corton: tight and stony when young, citrus and green apple over flint, with high acidity, a powerful, full body and a very long finish. Hazelnut, honey and toast take over after six to ten years.'),
  (15, 'A typical Meursault', 'France', 'Bourgogne', 'Meursault AOC', 'france.bourgogne.cote-de-beaune.meursault', 'WHITE'::wine_colour, 'STILL'::wine_style, 'Chardonnay', null, 3, 12, 87, 95, '{"appearanceIntensity":["MEDIUM_MINUS","MEDIUM"],"colourHue":["LEMON","GOLD"],"noseIntensity":["MEDIUM_PLUS","PRONOUNCED"],"development":["YOUTHFUL","DEVELOPING"],"sweetness":["DRY","DRY"],"acidity":["MEDIUM","MEDIUM_PLUS"],"tannin":["LOW","LOW"],"alcohol":["MEDIUM","MEDIUM"],"body":["MEDIUM_PLUS","FULL"],"flavourIntensity":["MEDIUM_PLUS","PRONOUNCED"],"finish":["MEDIUM_PLUS","LONG"]}'::jsonb, 'The broadest, richest Côte de Beaune white: ripe apple and peach with hazelnut, butter and toasty oak, a full body and medium(+) acidity. Rounder and nuttier than Puligny, less stony.'),
  (16, 'A typical Puligny-Montrachet', 'France', 'Bourgogne', 'Puligny-Montrachet AOC', 'france.bourgogne.cote-de-beaune.puligny-montrachet', 'WHITE'::wine_colour, 'STILL'::wine_style, 'Chardonnay', null, 3, 12, 88, 96, '{"appearanceIntensity":["PALE","MEDIUM"],"colourHue":["LEMON","GOLD"],"noseIntensity":["MEDIUM_PLUS","PRONOUNCED"],"development":["YOUTHFUL","DEVELOPING"],"sweetness":["DRY","DRY"],"acidity":["MEDIUM_PLUS","HIGH"],"tannin":["LOW","LOW"],"alcohol":["MEDIUM","MEDIUM"],"body":["MEDIUM","MEDIUM_PLUS"],"flavourIntensity":["MEDIUM_PLUS","PRONOUNCED"],"finish":["MEDIUM_PLUS","LONG"]}'::jsonb, 'Taut, mineral Côte de Beaune Chardonnay from Puligny: lemon, green apple and white flowers over a stony, flinty core, with high acidity and the oak in the background. Tighter and more linear than Meursault; hazelnut and honey come with age.'),
  (17, 'A typical Chassagne-Montrachet', 'France', 'Bourgogne', 'Chassagne-Montrachet AOC', 'france.bourgogne.cote-de-beaune.chassagne-montrachet', 'WHITE'::wine_colour, 'STILL'::wine_style, 'Chardonnay', null, 3, 12, 88, 96, '{"appearanceIntensity":["PALE","MEDIUM"],"colourHue":["LEMON","GOLD"],"noseIntensity":["MEDIUM_PLUS","PRONOUNCED"],"development":["YOUTHFUL","DEVELOPING"],"sweetness":["DRY","DRY"],"acidity":["MEDIUM_PLUS","HIGH"],"tannin":["LOW","LOW"],"alcohol":["MEDIUM","MEDIUM"],"body":["MEDIUM","MEDIUM_PLUS"],"flavourIntensity":["MEDIUM_PLUS","PRONOUNCED"],"finish":["MEDIUM_PLUS","LONG"]}'::jsonb, 'Côte de Beaune Chardonnay from Chassagne, Puligny''s southern neighbour: lemon, green apple and white flowers over a stony core with high acidity, usually a little broader than Puligny, with riper orchard fruit and a hint of hazelnut. Leaner than Meursault; honey and nutty notes come with age.'),
  (18, 'A typical Chablis Premier Cru', 'France', 'Bourgogne', 'Chablis Premier Cru', 'france.bourgogne.chablis.chablis.premier-cru', 'WHITE'::wine_colour, 'STILL'::wine_style, 'Chardonnay', null, 3, 15, 88, 96, '{"appearanceIntensity":["PALE","MEDIUM"],"colourHue":["LEMON_GREEN","GOLD"],"noseIntensity":["MEDIUM","MEDIUM_PLUS"],"development":["YOUTHFUL","DEVELOPING"],"sweetness":["DRY","DRY"],"acidity":["MEDIUM_PLUS","HIGH"],"tannin":["LOW","LOW"],"alcohol":["MEDIUM","MEDIUM"],"body":["MEDIUM","MEDIUM_PLUS"],"flavourIntensity":["MEDIUM_PLUS","PRONOUNCED"],"finish":["MEDIUM_PLUS","LONG"]}'::jsonb, 'Chablis from the named premier cru slopes: the village wine''s steely citrus and green apple with more concentration, a wet-stone, saline minerality and a longer finish, mostly unoaked. Unlike Côte de Beaune whites, the acidity stays high and the fruit never turns tropical.'),
  (19, 'A typical Chablis Grand Cru', 'France', 'Bourgogne', 'Chablis Grand Cru', 'france.bourgogne.chablis.chablis.chablis-grand-cru', 'WHITE'::wine_colour, 'STILL'::wine_style, 'Chardonnay', null, 5, 20, 90, 97, '{"appearanceIntensity":["PALE","MEDIUM"],"colourHue":["LEMON_GREEN","GOLD"],"noseIntensity":["MEDIUM_PLUS","PRONOUNCED"],"development":["YOUTHFUL","DEVELOPING"],"sweetness":["DRY","DRY"],"acidity":["MEDIUM_PLUS","HIGH"],"tannin":["LOW","LOW"],"alcohol":["MEDIUM","MEDIUM"],"body":["MEDIUM_PLUS","FULL"],"flavourIntensity":["PRONOUNCED","PRONOUNCED"],"finish":["LONG","LONG"]}'::jsonb, 'Chablis from the seven grand cru climats on the single slope above the town: the same steely citrus, green apple and wet-stone, saline minerality as premier cru, but more intense, fuller and longer, and more often matured in oak. Honey and hazelnut appear after five to ten years while the acidity stays high.'),
  (20, 'A typical Pouilly-Fuissé', 'France', 'Bourgogne', 'Pouilly-Fuissé AOC', 'france.bourgogne.maconnais.pouilly-fuisse', 'WHITE'::wine_colour, 'STILL'::wine_style, 'Chardonnay', null, 2, 8, 85, 93, '{"appearanceIntensity":["PALE","MEDIUM"],"colourHue":["LEMON","GOLD"],"noseIntensity":["MEDIUM","MEDIUM_PLUS"],"development":["YOUTHFUL","DEVELOPING"],"sweetness":["DRY","DRY"],"acidity":["MEDIUM","MEDIUM_PLUS"],"tannin":["LOW","LOW"],"alcohol":["MEDIUM","MEDIUM"],"body":["MEDIUM","MEDIUM_PLUS"],"flavourIntensity":["MEDIUM","MEDIUM_PLUS"],"finish":["MEDIUM","MEDIUM_PLUS"]}'::jsonb, 'The Mâconnais''s leading appellation: riper than Côte d''Or white, with apple, peach and melon fruit, a rounder medium(+) body and often some oak and butter. Acidity is medium to medium(+), without the tension of Chablis or Puligny.'),
  (21, 'A typical Bourgogne rouge', 'France', 'Bourgogne', 'Bourgogne AOC', 'france.bourgogne', 'RED'::wine_colour, 'STILL'::wine_style, 'Pinot Noir', null, 2, 6, 82, 90, '{"appearanceIntensity":["PALE","MEDIUM"],"colourHue":["RUBY","RUBY"],"noseIntensity":["MEDIUM_MINUS","MEDIUM"],"development":["YOUTHFUL","YOUTHFUL"],"sweetness":["DRY","DRY"],"acidity":["MEDIUM_PLUS","HIGH"],"tannin":["MEDIUM_MINUS","MEDIUM"],"alcohol":["MEDIUM","MEDIUM"],"body":["MEDIUM_MINUS","MEDIUM"],"flavourIntensity":["MEDIUM_MINUS","MEDIUM"],"finish":["MEDIUM_MINUS","MEDIUM"]}'::jsonb, 'Entry-level red Burgundy blended from across the region: simple red cherry, raspberry and strawberry, light-to-medium body, low-to-medium tannin and high acidity. A short-to-medium finish, little oak and little development.'),
  (22, 'A typical Bourgogne blanc', 'France', 'Bourgogne', 'Bourgogne AOC', 'france.bourgogne', 'WHITE'::wine_colour, 'STILL'::wine_style, 'Chardonnay', null, 1, 5, 82, 90, '{"appearanceIntensity":["PALE","MEDIUM_MINUS"],"colourHue":["LEMON_GREEN","LEMON"],"noseIntensity":["MEDIUM_MINUS","MEDIUM"],"development":["YOUTHFUL","YOUTHFUL"],"sweetness":["DRY","DRY"],"acidity":["MEDIUM","MEDIUM_PLUS"],"tannin":["LOW","LOW"],"alcohol":["MEDIUM","MEDIUM"],"body":["MEDIUM_MINUS","MEDIUM"],"flavourIntensity":["MEDIUM_MINUS","MEDIUM"],"finish":["MEDIUM_MINUS","MEDIUM"]}'::jsonb, 'Regional white Burgundy: unoaked or lightly oaked Chardonnay with apple, lemon and a touch of peach, medium(-) to medium body and fresh acidity. Simpler and shorter than any village wine, with a hint of butter from malolactic.'),
  (23, 'A typical Beaujolais cru', 'France', 'Beaujolais', 'Morgon AOC', 'france.beaujolais.morgon', 'RED'::wine_colour, 'STILL'::wine_style, 'Gamay', null, 2, 8, 84, 93, '{"appearanceIntensity":["MEDIUM_MINUS","MEDIUM"],"colourHue":["PURPLE","RUBY"],"noseIntensity":["MEDIUM","MEDIUM_PLUS"],"development":["YOUTHFUL","DEVELOPING"],"sweetness":["DRY","DRY"],"acidity":["MEDIUM_PLUS","HIGH"],"tannin":["MEDIUM_MINUS","MEDIUM"],"alcohol":["MEDIUM","MEDIUM"],"body":["MEDIUM_MINUS","MEDIUM"],"flavourIntensity":["MEDIUM","MEDIUM_PLUS"],"finish":["MEDIUM","MEDIUM_PLUS"]}'::jsonb, 'Gamay from the granite hills of northern Beaujolais (Morgon, Fleurie, Moulin-à-Vent and the other crus): bright red cherry, raspberry and violet, high acidity and light, supple tannin, with more depth and earthiness than basic Beaujolais. The sturdier crus age towards a Pinot-like savouriness.'),
  (24, 'A typical Pouilly-Fumé', 'France', 'Loire', 'Pouilly-Fumé AOC', 'france.loire.pouilly-fume', 'WHITE'::wine_colour, 'STILL'::wine_style, 'Sauvignon Blanc', null, 1, 5, 85, 93, '{"appearanceIntensity":["PALE","MEDIUM_MINUS"],"colourHue":["LEMON_GREEN","LEMON"],"noseIntensity":["MEDIUM_PLUS","PRONOUNCED"],"development":["YOUTHFUL","YOUTHFUL"],"sweetness":["DRY","DRY"],"acidity":["HIGH","HIGH"],"tannin":["LOW","LOW"],"alcohol":["MEDIUM","MEDIUM"],"body":["MEDIUM_MINUS","MEDIUM"],"flavourIntensity":["MEDIUM_PLUS","PRONOUNCED"],"finish":["MEDIUM","MEDIUM_PLUS"]}'::jsonb, 'Sauvignon Blanc from the bank opposite Sancerre: gooseberry, grapefruit and cut grass with the smoky, gunflint note that gives it its name, high acidity and no oak. A shade fuller and more mineral than Sancerre.'),
  (25, 'A typical Vouvray', 'France', 'Loire', 'Vouvray AOC', 'france.loire.vouvray', 'WHITE'::wine_colour, 'STILL'::wine_style, 'Chenin Blanc', null, 2, 15, 85, 94, '{"appearanceIntensity":["PALE","MEDIUM"],"colourHue":["LEMON","GOLD"],"noseIntensity":["MEDIUM","MEDIUM_PLUS"],"development":["YOUTHFUL","DEVELOPING"],"sweetness":["OFF_DRY","MEDIUM_SWEET"],"acidity":["HIGH","HIGH"],"tannin":["LOW","LOW"],"alcohol":["MEDIUM","MEDIUM"],"body":["MEDIUM","MEDIUM_PLUS"],"flavourIntensity":["MEDIUM","MEDIUM_PLUS"],"finish":["MEDIUM","MEDIUM_PLUS"]}'::jsonb, 'Chenin Blanc from Touraine limestone: quince, apple and pear with honey and a waxy, wet-wool note, high acidity and usually some residual sugar, from sec-tendre to demi-sec. The acidity keeps even the sweeter styles tasting fresh; honey and toast deepen over decades.'),
  (26, 'A typical Muscadet', 'France', 'Loire', 'Muscadet Sevre et Maine AOC', 'france.loire.muscadet-sevre-et-maine', 'WHITE'::wine_colour, 'STILL'::wine_style, 'Melon de Bourgogne', null, 1, 3, 80, 90, '{"appearanceIntensity":["PALE","PALE"],"colourHue":["LEMON_GREEN","LEMON"],"noseIntensity":["LIGHT","MEDIUM_MINUS"],"development":["YOUTHFUL","YOUTHFUL"],"sweetness":["DRY","DRY"],"acidity":["MEDIUM_PLUS","HIGH"],"tannin":["LOW","LOW"],"alcohol":["MEDIUM","MEDIUM"],"body":["LIGHT","MEDIUM_MINUS"],"flavourIntensity":["LIGHT","MEDIUM_MINUS"],"finish":["MEDIUM_MINUS","MEDIUM"]}'::jsonb, 'Melon de Bourgogne from near the Atlantic: pale, light and neutral, with lemon, green apple and a saline tang, high acidity and a light body. Ageing on its lees (sur lie) adds a faint bready note and a slight prickle.'),
  (27, 'A typical Chinon', 'France', 'Loire', 'Chinon AOC', 'france.loire.chinon', 'RED'::wine_colour, 'STILL'::wine_style, 'Cabernet Franc', null, 2, 10, 84, 92, '{"appearanceIntensity":["MEDIUM","MEDIUM"],"colourHue":["PURPLE","RUBY"],"noseIntensity":["MEDIUM","MEDIUM_PLUS"],"development":["YOUTHFUL","DEVELOPING"],"sweetness":["DRY","DRY"],"acidity":["MEDIUM_PLUS","HIGH"],"tannin":["MEDIUM","MEDIUM_PLUS"],"alcohol":["MEDIUM","MEDIUM"],"body":["MEDIUM_MINUS","MEDIUM"],"flavourIntensity":["MEDIUM","MEDIUM_PLUS"],"finish":["MEDIUM","MEDIUM_PLUS"]}'::jsonb, 'Loire Cabernet Franc: raspberry and red cherry with a leafy, green-pepper edge and a hint of violet, high acidity, medium body and fine, slightly grippy tannin. Little or no new oak; earthy and tobacco notes arrive with age.'),
  (28, 'A typical Condrieu', 'France', 'Rhône', 'Condrieu AOC', 'france.rhone.condrieu', 'WHITE'::wine_colour, 'STILL'::wine_style, 'Viognier', null, 1, 5, 87, 95, '{"appearanceIntensity":["MEDIUM_MINUS","MEDIUM"],"colourHue":["LEMON","GOLD"],"noseIntensity":["MEDIUM_PLUS","PRONOUNCED"],"development":["YOUTHFUL","YOUTHFUL"],"sweetness":["DRY","DRY"],"acidity":["MEDIUM_MINUS","MEDIUM"],"tannin":["LOW","LOW"],"alcohol":["MEDIUM","HIGH"],"body":["MEDIUM_PLUS","FULL"],"flavourIntensity":["MEDIUM_PLUS","PRONOUNCED"],"finish":["MEDIUM","MEDIUM_PLUS"]}'::jsonb, 'Viognier from steep granite in the northern Rhône: a heady nose of apricot, peach and honeysuckle, full body and high alcohol with low-to-medium acidity, which sets it apart from other aromatic whites. Usually drunk young, before the perfume fades.'),
  (29, 'A typical Hermitage', 'France', 'Rhône', 'Hermitage AOC', 'france.rhone.hermitage', 'RED'::wine_colour, 'STILL'::wine_style, 'Syrah', null, 8, 30, 90, 98, '{"appearanceIntensity":["MEDIUM_PLUS","DEEP"],"colourHue":["RUBY","GARNET"],"noseIntensity":["MEDIUM_PLUS","PRONOUNCED"],"development":["DEVELOPING","FULLY_DEVELOPED"],"sweetness":["DRY","DRY"],"acidity":["MEDIUM","MEDIUM_PLUS"],"tannin":["MEDIUM_PLUS","HIGH"],"alcohol":["MEDIUM","HIGH"],"body":["MEDIUM_PLUS","FULL"],"flavourIntensity":["MEDIUM_PLUS","PRONOUNCED"],"finish":["LONG","LONG"]}'::jsonb, 'Syrah from the steep granite hill above Tain: blackberry, black cherry, cracked black pepper, violet and a smoky, meaty edge, with high tannin, a full body and a long finish. Closed for its first decade; leather and game come with age. Fresher and more peppery than southern Rhône or Barossa Syrah, at moderate alcohol.'),
  (30, 'A typical Crozes-Hermitage', 'France', 'Rhône', 'Crozes-Hermitage AOC', 'france.rhone.crozes-hermitage', 'RED'::wine_colour, 'STILL'::wine_style, 'Syrah', null, 2, 8, 84, 92, '{"appearanceIntensity":["MEDIUM","DEEP"],"colourHue":["PURPLE","RUBY"],"noseIntensity":["MEDIUM","MEDIUM_PLUS"],"development":["YOUTHFUL","DEVELOPING"],"sweetness":["DRY","DRY"],"acidity":["MEDIUM","MEDIUM_PLUS"],"tannin":["MEDIUM","MEDIUM_PLUS"],"alcohol":["MEDIUM","MEDIUM"],"body":["MEDIUM","MEDIUM_PLUS"],"flavourIntensity":["MEDIUM","MEDIUM_PLUS"],"finish":["MEDIUM","MEDIUM_PLUS"]}'::jsonb, 'Syrah from the flatter land around the Hermitage hill, the largest northern Rhône appellation: blackberry, black cherry, black pepper and violet at medium body, with softer, medium tannin and a medium finish. Drunk young; lighter and simpler than Hermitage, just as peppery.'),
  (31, 'A typical Gigondas', 'France', 'Rhône', 'Gigondas AOC', 'france.rhone.gigondas', 'RED'::wine_colour, 'STILL'::wine_style, 'Grenache', 'Syrah', 4, 15, 86, 94, '{"appearanceIntensity":["MEDIUM","DEEP"],"colourHue":["RUBY","GARNET"],"noseIntensity":["MEDIUM_PLUS","PRONOUNCED"],"development":["YOUTHFUL","DEVELOPING"],"sweetness":["DRY","DRY"],"acidity":["MEDIUM_MINUS","MEDIUM"],"tannin":["MEDIUM_PLUS","HIGH"],"alcohol":["HIGH","HIGH"],"body":["MEDIUM_PLUS","FULL"],"flavourIntensity":["MEDIUM_PLUS","PRONOUNCED"],"finish":["MEDIUM_PLUS","LONG"]}'::jsonb, 'Southern Rhône Grenache with Syrah and Mourvèdre from higher, cooler slopes than Châteauneuf: kirsch-like black cherry, garrigue herbs and liquorice, high alcohol, and firmer, more rustic tannin than its neighbour. Leather and dried fruit build with age.'),
  (32, 'A typical Côtes du Rhône', 'France', 'Rhône', 'Cotes du Rhone AOC', 'france.rhone.cotes-du-rhone', 'RED'::wine_colour, 'STILL'::wine_style, 'Grenache', 'Syrah', 1, 5, 80, 89, '{"appearanceIntensity":["MEDIUM","MEDIUM_PLUS"],"colourHue":["PURPLE","RUBY"],"noseIntensity":["MEDIUM","MEDIUM_PLUS"],"development":["YOUTHFUL","YOUTHFUL"],"sweetness":["DRY","DRY"],"acidity":["MEDIUM_MINUS","MEDIUM"],"tannin":["MEDIUM","MEDIUM"],"alcohol":["MEDIUM","HIGH"],"body":["MEDIUM","MEDIUM_PLUS"],"flavourIntensity":["MEDIUM","MEDIUM_PLUS"],"finish":["MEDIUM_MINUS","MEDIUM"]}'::jsonb, 'Everyday southern Rhône blend led by Grenache: ripe raspberry and red cherry with a little pepper and dried herbs, medium body and soft, medium tannin, alcohol at the warm end. Simpler, shorter and fresher-fruited than Gigondas or Châteauneuf.'),
  (33, 'A typical Alsace Gewurztraminer', 'France', 'Alsace', 'Alsace AOC', 'france.alsace', 'WHITE'::wine_colour, 'STILL'::wine_style, 'Gewürztraminer', null, 1, 6, 85, 93, '{"appearanceIntensity":["MEDIUM_MINUS","MEDIUM_PLUS"],"colourHue":["LEMON","GOLD"],"noseIntensity":["PRONOUNCED","PRONOUNCED"],"development":["YOUTHFUL","DEVELOPING"],"sweetness":["OFF_DRY","MEDIUM_DRY"],"acidity":["LOW","MEDIUM_MINUS"],"tannin":["LOW","LOW"],"alcohol":["MEDIUM","HIGH"],"body":["MEDIUM_PLUS","FULL"],"flavourIntensity":["MEDIUM_PLUS","PRONOUNCED"],"finish":["MEDIUM","MEDIUM_PLUS"]}'::jsonb, 'Alsace''s most aromatic white: a pronounced nose of lychee, rose and sweet spice, deep lemon to gold colour, an oily, full body, high alcohol and low acidity, often with a touch of residual sugar. The low acidity and oily weight separate it from Muscat or Riesling.'),
  (34, 'A typical Alsace Pinot Gris', 'France', 'Alsace', 'Alsace AOC', 'france.alsace', 'WHITE'::wine_colour, 'STILL'::wine_style, 'Pinot Gris', null, 2, 8, 85, 92, '{"appearanceIntensity":["MEDIUM_MINUS","MEDIUM_PLUS"],"colourHue":["LEMON","GOLD"],"noseIntensity":["MEDIUM","MEDIUM_PLUS"],"development":["YOUTHFUL","DEVELOPING"],"sweetness":["DRY","MEDIUM_DRY"],"acidity":["MEDIUM_MINUS","MEDIUM"],"tannin":["LOW","LOW"],"alcohol":["MEDIUM","HIGH"],"body":["MEDIUM_PLUS","FULL"],"flavourIntensity":["MEDIUM","MEDIUM_PLUS"],"finish":["MEDIUM","MEDIUM_PLUS"]}'::jsonb, 'Alsace Pinot Gris is nothing like Italian Pinot Grigio: full-bodied and often off-dry, with ripe pear, peach and apricot, a smoky, honeyed edge and medium acidity. Richer and less perfumed than Gewurztraminer, broader and less acidic than Riesling.'),
  (35, 'A typical Provence rosé', 'France', 'Provence', 'Côtes de Provence AOC', 'france.provence.cotes-de-provence', 'ROSE'::wine_colour, 'STILL'::wine_style, 'Grenache', 'Cinsault', 0, 2, 80, 90, '{"appearanceIntensity":["PALE","PALE"],"colourHue":["PINK","SALMON"],"noseIntensity":["MEDIUM_MINUS","MEDIUM"],"development":["YOUTHFUL","YOUTHFUL"],"sweetness":["DRY","DRY"],"acidity":["MEDIUM","MEDIUM_PLUS"],"tannin":["LOW","LOW"],"alcohol":["MEDIUM","MEDIUM"],"body":["MEDIUM_MINUS","MEDIUM"],"flavourIntensity":["MEDIUM_MINUS","MEDIUM"],"finish":["MEDIUM_MINUS","MEDIUM"]}'::jsonb, 'Pale, dry Grenache–Cinsault rosé made by direct pressing: very pale pink to salmon, delicate strawberry, redcurrant and peach with a citrus lift, crisp acidity and a light-to-medium body. Drunk within a year or two.'),
  (36, 'A typical Cahors', 'France', 'Sud Ouest', 'Cahors AOC', 'france.sud-ouest.cahors', 'RED'::wine_colour, 'STILL'::wine_style, 'Malbec', 'Merlot', 4, 15, 84, 92, '{"appearanceIntensity":["DEEP","DEEP"],"colourHue":["PURPLE","RUBY"],"noseIntensity":["MEDIUM","MEDIUM_PLUS"],"development":["YOUTHFUL","DEVELOPING"],"sweetness":["DRY","DRY"],"acidity":["MEDIUM_PLUS","HIGH"],"tannin":["MEDIUM_PLUS","HIGH"],"alcohol":["MEDIUM","MEDIUM"],"body":["MEDIUM_PLUS","FULL"],"flavourIntensity":["MEDIUM","MEDIUM_PLUS"],"finish":["MEDIUM","MEDIUM_PLUS"]}'::jsonb, 'The ''black wine'' of south-west France: Malbec (Côt) with a little Merlot, near-opaque, with black plum, blackberry and violet, high, rustic tannin and fresh acidity. Leaner, earthier and more tannic than Mendoza Malbec, at lower alcohol.'),
  (37, 'A typical Barolo', 'Italy', 'Piemonte', 'Barolo DOCG', 'italy.piemonte.barolo', 'RED'::wine_colour, 'STILL'::wine_style, 'Nebbiolo', null, 8, 30, 89, 97, '{"appearanceIntensity":["PALE","MEDIUM"],"colourHue":["GARNET","GARNET"],"noseIntensity":["MEDIUM_PLUS","PRONOUNCED"],"development":["DEVELOPING","FULLY_DEVELOPED"],"sweetness":["DRY","DRY"],"acidity":["MEDIUM_PLUS","HIGH"],"tannin":["HIGH","HIGH"],"alcohol":["MEDIUM","HIGH"],"body":["MEDIUM_PLUS","FULL"],"flavourIntensity":["MEDIUM_PLUS","PRONOUNCED"],"finish":["LONG","LONG"]}'::jsonb, 'Nebbiolo from the Langhe: pale garnet with an orange rim that belies its structure, a nose of rose, tar, red cherry and liquorice, then high acidity and high, drying tannin. More tannic and longer-lived than Barbaresco; it needs a decade to soften.'),
  (38, 'A typical Barbaresco', 'Italy', 'Piemonte', 'Barbaresco DOCG', 'italy.piemonte.barbaresco', 'RED'::wine_colour, 'STILL'::wine_style, 'Nebbiolo', null, 6, 20, 88, 96, '{"appearanceIntensity":["PALE","MEDIUM"],"colourHue":["GARNET","GARNET"],"noseIntensity":["MEDIUM_PLUS","PRONOUNCED"],"development":["DEVELOPING","FULLY_DEVELOPED"],"sweetness":["DRY","DRY"],"acidity":["MEDIUM_PLUS","HIGH"],"tannin":["MEDIUM_PLUS","HIGH"],"alcohol":["MEDIUM","HIGH"],"body":["MEDIUM","MEDIUM_PLUS"],"flavourIntensity":["MEDIUM_PLUS","PRONOUNCED"],"finish":["MEDIUM_PLUS","LONG"]}'::jsonb, 'Nebbiolo from the other side of Alba: the same rose, red cherry and tar as Barolo, pale garnet with high acidity, but a little lighter in body, with slightly softer, earlier-resolving tannin and more perfume. Approachable a few years sooner.'),
  (39, 'A typical Barbera d''Asti', 'Italy', 'Piemonte', 'Barbera d''Asti DOCG', 'italy.piemonte.barbera-dasti', 'RED'::wine_colour, 'STILL'::wine_style, 'Barbera', null, 2, 8, 83, 92, '{"appearanceIntensity":["MEDIUM","DEEP"],"colourHue":["PURPLE","RUBY"],"noseIntensity":["MEDIUM","MEDIUM_PLUS"],"development":["YOUTHFUL","DEVELOPING"],"sweetness":["DRY","DRY"],"acidity":["HIGH","HIGH"],"tannin":["MEDIUM_MINUS","MEDIUM"],"alcohol":["MEDIUM","HIGH"],"body":["MEDIUM","MEDIUM_PLUS"],"flavourIntensity":["MEDIUM","MEDIUM_PLUS"],"finish":["MEDIUM","MEDIUM_PLUS"]}'::jsonb, 'Piedmont''s everyday red: deep ruby, juicy red and black cherry and plum, high acidity with low-to-medium tannin, the reverse of Nebbiolo''s structure. Oaked versions add vanilla and spice.'),
  (40, 'A typical Gavi', 'Italy', 'Piemonte', 'Gavi DOCG', 'italy.piemonte.gavi', 'WHITE'::wine_colour, 'STILL'::wine_style, 'Cortese', null, 1, 3, 80, 89, '{"appearanceIntensity":["PALE","PALE"],"colourHue":["LEMON_GREEN","LEMON"],"noseIntensity":["MEDIUM_MINUS","MEDIUM"],"development":["YOUTHFUL","YOUTHFUL"],"sweetness":["DRY","DRY"],"acidity":["MEDIUM_PLUS","HIGH"],"tannin":["LOW","LOW"],"alcohol":["MEDIUM","MEDIUM"],"body":["MEDIUM_MINUS","MEDIUM"],"flavourIntensity":["MEDIUM_MINUS","MEDIUM"],"finish":["MEDIUM_MINUS","MEDIUM"]}'::jsonb, 'Cortese from south-east Piedmont: pale, crisp and restrained, with lemon, green apple and pear, a hint of white flowers and a bitter-almond finish. High acidity, a light-to-medium body and no oak.'),
  (41, 'A typical Amarone', 'Italy', 'Veneto', 'Amarone della Valpolicella DOCG', 'italy.veneto.amarone-della-valpolicella', 'RED'::wine_colour, 'STILL'::wine_style, 'Corvina', 'Rondinella', 6, 20, 88, 96, '{"appearanceIntensity":["MEDIUM_PLUS","DEEP"],"colourHue":["RUBY","GARNET"],"noseIntensity":["MEDIUM_PLUS","PRONOUNCED"],"development":["DEVELOPING","FULLY_DEVELOPED"],"sweetness":["DRY","OFF_DRY"],"acidity":["MEDIUM","MEDIUM_PLUS"],"tannin":["MEDIUM_PLUS","HIGH"],"alcohol":["HIGH","HIGH"],"body":["FULL","FULL"],"flavourIntensity":["MEDIUM_PLUS","PRONOUNCED"],"finish":["LONG","LONG"]}'::jsonb, 'Valpolicella made from grapes dried for months before fermentation: deep, with raisin, prune and kirsch-like dried cherry, chocolate and spice, high alcohol (15 % and more) and a full, almost sweet-seeming body although it is dry. The dried-grape character gives it away.'),
  (42, 'A typical Valpolicella Ripasso', 'Italy', 'Veneto', 'Valpolicella Ripasso DOC', 'italy.veneto.valpolicella-ripasso', 'RED'::wine_colour, 'STILL'::wine_style, 'Corvina', 'Rondinella', 3, 8, 83, 91, '{"appearanceIntensity":["MEDIUM","MEDIUM_PLUS"],"colourHue":["RUBY","GARNET"],"noseIntensity":["MEDIUM","MEDIUM_PLUS"],"development":["YOUTHFUL","DEVELOPING"],"sweetness":["DRY","DRY"],"acidity":["MEDIUM","MEDIUM_PLUS"],"tannin":["MEDIUM","MEDIUM"],"alcohol":["MEDIUM","HIGH"],"body":["MEDIUM","MEDIUM_PLUS"],"flavourIntensity":["MEDIUM","MEDIUM_PLUS"],"finish":["MEDIUM","MEDIUM_PLUS"]}'::jsonb, 'Valpolicella refermented on the pressed skins left from Amarone: sour red cherry from Corvina with a layer of cooked cherry, raisin and sweet spice, medium(+) body and acidity. A halfway house between light Valpolicella and Amarone.'),
  (43, 'A typical Soave', 'Italy', 'Veneto', 'Soave DOC', 'italy.veneto.soave', 'WHITE'::wine_colour, 'STILL'::wine_style, 'Garganega', null, 1, 5, 80, 91, '{"appearanceIntensity":["PALE","MEDIUM_MINUS"],"colourHue":["LEMON","LEMON"],"noseIntensity":["MEDIUM_MINUS","MEDIUM"],"development":["YOUTHFUL","YOUTHFUL"],"sweetness":["DRY","DRY"],"acidity":["MEDIUM","MEDIUM_PLUS"],"tannin":["LOW","LOW"],"alcohol":["MEDIUM","MEDIUM"],"body":["MEDIUM_MINUS","MEDIUM"],"flavourIntensity":["MEDIUM_MINUS","MEDIUM"],"finish":["MEDIUM_MINUS","MEDIUM"]}'::jsonb, 'Garganega from volcanic hills east of Verona: pear, apple and citrus with chamomile and a bitter-almond finish, medium acidity and a light, slightly textured body. Classico and single-vineyard wines add a stony, saline note.'),
  (44, 'A typical Prosecco', 'Italy', 'Prosecco', 'Prosecco DOC', 'italy.veneto.prosecco', 'WHITE'::wine_colour, 'SPARKLING'::wine_style, 'Glera', null, null, null, 78, 88, '{"appearanceIntensity":["PALE","PALE"],"colourHue":["LEMON_GREEN","LEMON"],"noseIntensity":["MEDIUM_MINUS","MEDIUM"],"development":["YOUTHFUL","YOUTHFUL"],"sweetness":["OFF_DRY","MEDIUM_DRY"],"acidity":["MEDIUM","MEDIUM_PLUS"],"tannin":["LOW","LOW"],"alcohol":["LOW","MEDIUM"],"body":["LIGHT","MEDIUM_MINUS"],"flavourIntensity":["MEDIUM_MINUS","MEDIUM"],"finish":["SHORT","MEDIUM_MINUS"],"mousse":["CREAMY","AGGRESSIVE"]}'::jsonb, 'Tank-method sparkling Glera from north-east Italy: pale, with pear, green apple, melon and white flowers, no bready autolysis, a light body and a frothy, less persistent mousse. Usually a touch of sweetness (Brut or Extra Dry) and drunk young.'),
  (45, 'A typical Franciacorta', 'Italy', 'Lombardia', 'Franciacorta DOCG', 'italy.lombardia.franciacorta', 'WHITE'::wine_colour, 'SPARKLING'::wine_style, 'Chardonnay', 'Pinot Noir', null, null, 86, 93, '{"appearanceIntensity":["PALE","MEDIUM"],"colourHue":["LEMON","GOLD"],"noseIntensity":["MEDIUM","MEDIUM_PLUS"],"development":["YOUTHFUL","DEVELOPING"],"sweetness":["DRY","DRY"],"acidity":["MEDIUM","MEDIUM_PLUS"],"tannin":["LOW","LOW"],"alcohol":["MEDIUM","MEDIUM"],"body":["MEDIUM","MEDIUM_PLUS"],"flavourIntensity":["MEDIUM","MEDIUM_PLUS"],"finish":["MEDIUM","MEDIUM_PLUS"],"mousse":["DELICATE","CREAMY"]}'::jsonb, 'Italy''s bottle-fermented sparkling from Chardonnay and Pinot Noir by Lake Iseo: riper yellow apple and peach, brioche from long lees ageing, softer medium(+) acidity and a fine, creamy mousse. Rounder and less sharp than Champagne.'),
  (46, 'A typical Chianti Classico', 'Italy', 'Toscana', 'Chianti Classico DOCG', 'italy.toscana.chianti-classico', 'RED'::wine_colour, 'STILL'::wine_style, 'Sangiovese', 'Merlot', 3, 12, 84, 94, '{"appearanceIntensity":["MEDIUM_MINUS","MEDIUM"],"colourHue":["RUBY","GARNET"],"noseIntensity":["MEDIUM","MEDIUM_PLUS"],"development":["YOUTHFUL","DEVELOPING"],"sweetness":["DRY","DRY"],"acidity":["MEDIUM_PLUS","HIGH"],"tannin":["MEDIUM_PLUS","HIGH"],"alcohol":["MEDIUM","MEDIUM"],"body":["MEDIUM","MEDIUM_PLUS"],"flavourIntensity":["MEDIUM","MEDIUM_PLUS"],"finish":["MEDIUM","MEDIUM_PLUS"]}'::jsonb, 'Sangiovese from the hills between Florence and Siena: sour red cherry and plum, dried herbs, a savoury tomato-leaf note and earth, high acidity and high, slightly drying tannin at medium body. More rustic and savoury than Pinot Noir, lighter in colour than Bordeaux.'),
  (47, 'A typical Brunello di Montalcino', 'Italy', 'Toscana', 'Brunello di Montalcino DOCG', 'italy.toscana.brunello-di-montalcino', 'RED'::wine_colour, 'STILL'::wine_style, 'Sangiovese', null, 8, 25, 88, 97, '{"appearanceIntensity":["MEDIUM_MINUS","MEDIUM"],"colourHue":["RUBY","GARNET"],"noseIntensity":["MEDIUM_PLUS","PRONOUNCED"],"development":["DEVELOPING","FULLY_DEVELOPED"],"sweetness":["DRY","DRY"],"acidity":["MEDIUM_PLUS","HIGH"],"tannin":["MEDIUM_PLUS","HIGH"],"alcohol":["MEDIUM","HIGH"],"body":["MEDIUM_PLUS","FULL"],"flavourIntensity":["MEDIUM_PLUS","PRONOUNCED"],"finish":["MEDIUM_PLUS","LONG"]}'::jsonb, 'Riper, fuller Sangiovese from warmer Montalcino, aged for years in cask before release: red and cooked cherry, leather, tobacco and dried herbs, high acidity and high tannin over a medium(+) to full body. More power and tertiary character than Chianti Classico.'),
  (48, 'A typical Bolgheri', 'Italy', 'Toscana', 'Bolgheri DOC', 'italy.toscana.bolgheri', 'RED'::wine_colour, 'STILL'::wine_style, 'Cabernet Sauvignon', 'Merlot', 5, 20, 88, 96, '{"appearanceIntensity":["MEDIUM_PLUS","DEEP"],"colourHue":["RUBY","GARNET"],"noseIntensity":["MEDIUM_PLUS","PRONOUNCED"],"development":["YOUTHFUL","DEVELOPING"],"sweetness":["DRY","DRY"],"acidity":["MEDIUM","MEDIUM_PLUS"],"tannin":["MEDIUM_PLUS","HIGH"],"alcohol":["MEDIUM","HIGH"],"body":["MEDIUM_PLUS","FULL"],"flavourIntensity":["MEDIUM_PLUS","PRONOUNCED"],"finish":["MEDIUM_PLUS","LONG"]}'::jsonb, 'Bordeaux varieties on the Tuscan coast: riper than Bordeaux, with sweet blackcurrant and black cherry, Mediterranean herbs, vanilla and mint, full body, ripe high tannin and warmer alcohol. Plusher than Pauillac, fresher than Napa.'),
  (49, 'A typical Montepulciano d''Abruzzo', 'Italy', 'Abruzzo', 'Montepulciano d''Abruzzo DOC', 'italy.abruzzo.montepulciano-d-abruzzo', 'RED'::wine_colour, 'STILL'::wine_style, 'Montepulciano', null, 1, 6, 78, 89, '{"appearanceIntensity":["DEEP","DEEP"],"colourHue":["PURPLE","RUBY"],"noseIntensity":["MEDIUM","MEDIUM_PLUS"],"development":["YOUTHFUL","DEVELOPING"],"sweetness":["DRY","DRY"],"acidity":["MEDIUM","MEDIUM_PLUS"],"tannin":["MEDIUM","MEDIUM_PLUS"],"alcohol":["MEDIUM","HIGH"],"body":["MEDIUM","MEDIUM_PLUS"],"flavourIntensity":["MEDIUM","MEDIUM_PLUS"],"finish":["MEDIUM","MEDIUM_PLUS"]}'::jsonb, 'Abruzzo''s workhorse red: deeply coloured, with black cherry, plum and blackberry, a herbal, liquorice note, medium(+) acidity and plentiful but soft tannin. Juicy and uncomplicated at the basic level.'),
  (50, 'A typical Taurasi', 'Italy', 'Campania', 'Taurasi DOCG', 'italy.campania.taurasi', 'RED'::wine_colour, 'STILL'::wine_style, 'Aglianico', null, 8, 25, 86, 94, '{"appearanceIntensity":["MEDIUM_PLUS","DEEP"],"colourHue":["RUBY","GARNET"],"noseIntensity":["MEDIUM_PLUS","PRONOUNCED"],"development":["DEVELOPING","FULLY_DEVELOPED"],"sweetness":["DRY","DRY"],"acidity":["MEDIUM_PLUS","HIGH"],"tannin":["HIGH","HIGH"],"alcohol":["MEDIUM","HIGH"],"body":["MEDIUM_PLUS","FULL"],"flavourIntensity":["MEDIUM_PLUS","PRONOUNCED"],"finish":["MEDIUM_PLUS","LONG"]}'::jsonb, 'Aglianico from volcanic Irpinia in Campania: deep colour, black cherry and plum with earth, smoke and leather, high acidity and very high, austere tannin. Often called the Barolo of the south, but darker in colour and fruit than Nebbiolo.'),
  (51, 'A typical Etna Rosso', 'Italy', 'Sicilia', 'Etna Rosso DOC', 'italy.sicilia.etna', 'RED'::wine_colour, 'STILL'::wine_style, 'Nerello Mascalese', 'Nerello Cappuccio', 3, 12, 85, 94, '{"appearanceIntensity":["PALE","MEDIUM"],"colourHue":["RUBY","GARNET"],"noseIntensity":["MEDIUM","MEDIUM_PLUS"],"development":["YOUTHFUL","DEVELOPING"],"sweetness":["DRY","DRY"],"acidity":["MEDIUM_PLUS","HIGH"],"tannin":["MEDIUM","MEDIUM_PLUS"],"alcohol":["MEDIUM","HIGH"],"body":["MEDIUM","MEDIUM"],"flavourIntensity":["MEDIUM","MEDIUM_PLUS"],"finish":["MEDIUM","MEDIUM_PLUS"]}'::jsonb, 'Nerello Mascalese from the high volcanic slopes of Etna: pale, with red cherry and raspberry, dried herbs and a smoky, flinty note, high acidity and fine but firm tannin. Often likened to Burgundy or Nebbiolo; much lighter in colour than most southern reds.'),
  (52, 'A typical Primitivo', 'Italy', 'Puglia', 'Primitivo di Manduria DOC', 'italy.puglia.primitivo-di-manduria', 'RED'::wine_colour, 'STILL'::wine_style, 'Primitivo', null, 2, 6, 80, 90, '{"appearanceIntensity":["DEEP","DEEP"],"colourHue":["PURPLE","RUBY"],"noseIntensity":["MEDIUM_PLUS","PRONOUNCED"],"development":["YOUTHFUL","DEVELOPING"],"sweetness":["DRY","OFF_DRY"],"acidity":["MEDIUM_MINUS","MEDIUM"],"tannin":["MEDIUM","MEDIUM_PLUS"],"alcohol":["HIGH","HIGH"],"body":["MEDIUM_PLUS","FULL"],"flavourIntensity":["MEDIUM_PLUS","PRONOUNCED"],"finish":["MEDIUM","MEDIUM_PLUS"]}'::jsonb, 'Primitivo (Zinfandel) from hot southern Puglia: deep, jammy black plum and blackberry with dried-fruit, vanilla and chocolate notes, high alcohol, soft acidity and often a hint of residual sugar. Riper and softer than any northern Italian red.'),
  (53, 'A typical Rioja Reserva', 'Spain', 'Rioja', 'Rioja DOCa', 'spain.la-rioja', 'RED'::wine_colour, 'STILL'::wine_style, 'Tempranillo', 'Grenache', 5, 15, 86, 93, '{"appearanceIntensity":["MEDIUM","MEDIUM_PLUS"],"colourHue":["RUBY","GARNET"],"noseIntensity":["MEDIUM","MEDIUM_PLUS"],"development":["DEVELOPING","FULLY_DEVELOPED"],"sweetness":["DRY","DRY"],"acidity":["MEDIUM","MEDIUM_PLUS"],"tannin":["MEDIUM","MEDIUM_PLUS"],"alcohol":["MEDIUM","HIGH"],"body":["MEDIUM","MEDIUM_PLUS"],"flavourIntensity":["MEDIUM","MEDIUM_PLUS"],"finish":["MEDIUM","MEDIUM_PLUS"]}'::jsonb, 'Tempranillo with some Garnacha, aged at least three years, one of them in (often American) oak: red cherry and plum wrapped in vanilla, coconut and dill, with leather and tobacco developing. Medium body, medium acidity and smooth, medium tannin.'),
  (54, 'A typical Rioja Gran Reserva', 'Spain', 'Rioja', 'Rioja DOCa', 'spain.la-rioja', 'RED'::wine_colour, 'STILL'::wine_style, 'Tempranillo', 'Grenache', 10, 30, 87, 95, '{"appearanceIntensity":["MEDIUM_MINUS","MEDIUM"],"colourHue":["GARNET","TAWNY"],"noseIntensity":["MEDIUM","MEDIUM_PLUS"],"development":["DEVELOPING","FULLY_DEVELOPED"],"sweetness":["DRY","DRY"],"acidity":["MEDIUM","MEDIUM_PLUS"],"tannin":["MEDIUM_MINUS","MEDIUM"],"alcohol":["MEDIUM","MEDIUM"],"body":["MEDIUM","MEDIUM"],"flavourIntensity":["MEDIUM","MEDIUM_PLUS"],"finish":["MEDIUM_PLUS","LONG"]}'::jsonb, 'Rioja from a selected vintage, aged at least five years with two in oak: pale garnet to tawny, with dried red fruit, leather, tobacco and sweet vanilla-and-dill oak, softened medium tannin and fresh acidity. Tertiary rather than fruity; the oak has melted into the wine.'),
  (55, 'A typical Ribera del Duero', 'Spain', 'Ribera del Duero', 'Ribera del Duero DO', 'spain.castilla-y-leon.ribera-del-duero', 'RED'::wine_colour, 'STILL'::wine_style, 'Tempranillo', null, 4, 15, 86, 95, '{"appearanceIntensity":["MEDIUM_PLUS","DEEP"],"colourHue":["PURPLE","RUBY"],"noseIntensity":["MEDIUM_PLUS","PRONOUNCED"],"development":["YOUTHFUL","DEVELOPING"],"sweetness":["DRY","DRY"],"acidity":["MEDIUM","MEDIUM_PLUS"],"tannin":["MEDIUM_PLUS","HIGH"],"alcohol":["MEDIUM","HIGH"],"body":["MEDIUM_PLUS","FULL"],"flavourIntensity":["MEDIUM_PLUS","PRONOUNCED"],"finish":["MEDIUM_PLUS","LONG"]}'::jsonb, 'Tempranillo (Tinto Fino) from the high plateau of the Duero: deeper, darker and more tannic than Rioja, with blackberry and black plum, liquorice and French-oak toast and chocolate. Full body and firm tannin, freshened by the cool nights of the altitude.'),
  (56, 'A typical Priorat', 'Spain', 'Priorat', 'Priorat DOQ', 'spain.cataluna.priorat', 'RED'::wine_colour, 'STILL'::wine_style, 'Grenache', 'Carignan', 5, 15, 88, 96, '{"appearanceIntensity":["DEEP","DEEP"],"colourHue":["RUBY","GARNET"],"noseIntensity":["MEDIUM_PLUS","PRONOUNCED"],"development":["YOUTHFUL","DEVELOPING"],"sweetness":["DRY","DRY"],"acidity":["MEDIUM","MEDIUM_PLUS"],"tannin":["MEDIUM_PLUS","HIGH"],"alcohol":["HIGH","HIGH"],"body":["MEDIUM_PLUS","FULL"],"flavourIntensity":["MEDIUM_PLUS","PRONOUNCED"],"finish":["MEDIUM_PLUS","LONG"]}'::jsonb, 'Old-vine Garnacha and Cariñena on black llicorella slate in Catalonia: deep, concentrated black fruit, liquorice and garrigue with a stony, mineral core, high alcohol (often 15 %) and firm tannin. Denser and more mineral than southern Rhône Grenache.'),
  (57, 'A typical Bierzo', 'Spain', 'Castilla y Leon', 'Bierzo DO', 'spain.castilla-y-leon.bierzo', 'RED'::wine_colour, 'STILL'::wine_style, 'Mencía', null, 2, 8, 84, 93, '{"appearanceIntensity":["MEDIUM","MEDIUM_PLUS"],"colourHue":["PURPLE","RUBY"],"noseIntensity":["MEDIUM_PLUS","PRONOUNCED"],"development":["YOUTHFUL","DEVELOPING"],"sweetness":["DRY","DRY"],"acidity":["MEDIUM_PLUS","HIGH"],"tannin":["MEDIUM","MEDIUM_PLUS"],"alcohol":["MEDIUM","MEDIUM"],"body":["MEDIUM","MEDIUM"],"flavourIntensity":["MEDIUM","MEDIUM_PLUS"],"finish":["MEDIUM","MEDIUM_PLUS"]}'::jsonb, 'Mencía from slate slopes in north-west Spain: vivid red cherry, raspberry and blackberry with violet and herbal notes, high acidity, medium body and fine, medium tannin. Fresh and aromatic, often compared with Cabernet Franc or cru Beaujolais.'),
  (58, 'A typical Rías Baixas Albariño', 'Spain', 'Rías Baixas', 'Rías Baixas DO', 'spain.galicia.rias-baixas', 'WHITE'::wine_colour, 'STILL'::wine_style, 'Albariño', null, 0, 3, 84, 91, '{"appearanceIntensity":["PALE","PALE"],"colourHue":["LEMON_GREEN","LEMON"],"noseIntensity":["MEDIUM","MEDIUM_PLUS"],"development":["YOUTHFUL","YOUTHFUL"],"sweetness":["DRY","DRY"],"acidity":["MEDIUM_PLUS","HIGH"],"tannin":["LOW","LOW"],"alcohol":["MEDIUM","MEDIUM"],"body":["MEDIUM_MINUS","MEDIUM"],"flavourIntensity":["MEDIUM","MEDIUM_PLUS"],"finish":["MEDIUM","MEDIUM_PLUS"]}'::jsonb, 'Albariño from the Atlantic coast of Galicia: pale, aromatic and dry, with peach, citrus and white blossom, high acidity and a distinctly saline, sea-spray finish. More aromatic and stone-fruited than Muscadet, lighter than Viognier.'),
  (59, 'A typical Rueda Verdejo', 'Spain', 'Castilla y Leon', 'Rueda DO', 'spain.castilla-y-leon.rueda', 'WHITE'::wine_colour, 'STILL'::wine_style, 'Verdejo', null, 0, 2, 80, 89, '{"appearanceIntensity":["PALE","PALE"],"colourHue":["LEMON_GREEN","LEMON"],"noseIntensity":["MEDIUM","MEDIUM_PLUS"],"development":["YOUTHFUL","YOUTHFUL"],"sweetness":["DRY","DRY"],"acidity":["MEDIUM","MEDIUM_PLUS"],"tannin":["LOW","LOW"],"alcohol":["MEDIUM","MEDIUM"],"body":["MEDIUM_MINUS","MEDIUM"],"flavourIntensity":["MEDIUM","MEDIUM_PLUS"],"finish":["MEDIUM_MINUS","MEDIUM"]}'::jsonb, 'Verdejo from the high plains of Castilla y León: pale, with citrus, cut grass and a distinctive fennel-like herbal note, medium(+) acidity and a slightly bitter-almond finish. Close to Sauvignon Blanc, but less pungent and a little broader.'),
  (60, 'A typical Fino', 'Spain', 'Jerez', 'Jerez-Xérès-Sherry', 'spain.andalucia.jerez', 'WHITE'::wine_colour, 'FORTIFIED'::wine_style, 'Palomino', null, null, null, 85, 93, '{"appearanceIntensity":["PALE","PALE"],"colourHue":["LEMON","LEMON"],"noseIntensity":["MEDIUM","MEDIUM_PLUS"],"development":["DEVELOPING","FULLY_DEVELOPED"],"sweetness":["DRY","DRY"],"acidity":["MEDIUM","MEDIUM_PLUS"],"tannin":["LOW","LOW"],"alcohol":["LOW","MEDIUM_MINUS"],"body":["LIGHT","MEDIUM_MINUS"],"flavourIntensity":["MEDIUM","MEDIUM_PLUS"],"finish":["MEDIUM","MEDIUM_PLUS"]}'::jsonb, 'Palomino aged under a blanket of flor yeast in the bodegas of Jerez and El Puerto de Santa María: very pale, bone dry and light-bodied, with bread dough, bruised-apple acetaldehyde, almond and a saline edge at about 15 % alcohol. A little broader and less salty than Manzanilla.'),
  (61, 'A typical Manzanilla', 'Spain', 'Andalucia', 'Manzanilla Sanlucar de Barrameda DO', 'spain.andalucia', 'WHITE'::wine_colour, 'FORTIFIED'::wine_style, 'Palomino', null, null, null, 85, 93, '{"appearanceIntensity":["PALE","PALE"],"colourHue":["LEMON","LEMON"],"noseIntensity":["MEDIUM","MEDIUM_PLUS"],"development":["DEVELOPING","FULLY_DEVELOPED"],"sweetness":["DRY","DRY"],"acidity":["MEDIUM","MEDIUM_PLUS"],"tannin":["LOW","LOW"],"alcohol":["LOW","MEDIUM_MINUS"],"body":["LIGHT","MEDIUM_MINUS"],"flavourIntensity":["MEDIUM","MEDIUM_PLUS"],"finish":["MEDIUM","MEDIUM_PLUS"]}'::jsonb, 'Fino-style sherry aged under flor in the seaside bodegas of Sanlúcar de Barrameda, where the humid air keeps the flor thick all year: very pale, bone dry and light, with a pronounced saline tang, chamomile, bread dough and bruised-apple acetaldehyde at about 15 % alcohol. More delicate and saltier than Fino from Jerez.'),
  (62, 'A typical Oloroso', 'Spain', 'Jerez', 'Jerez-Xérès-Sherry', 'spain.andalucia.jerez', 'WHITE'::wine_colour, 'FORTIFIED'::wine_style, 'Palomino', null, null, null, 86, 94, '{"appearanceIntensity":["MEDIUM_PLUS","DEEP"],"colourHue":["AMBER","BROWN"],"noseIntensity":["MEDIUM_PLUS","PRONOUNCED"],"development":["FULLY_DEVELOPED","FULLY_DEVELOPED"],"sweetness":["DRY","DRY"],"acidity":["MEDIUM","MEDIUM_PLUS"],"tannin":["LOW","LOW"],"alcohol":["MEDIUM","MEDIUM_PLUS"],"body":["MEDIUM_PLUS","FULL"],"flavourIntensity":["MEDIUM_PLUS","PRONOUNCED"],"finish":["LONG","LONG"]}'::jsonb, 'Sherry aged oxidatively, without flor, for years in the solera: amber to brown, with walnut, hazelnut, toffee and dried fruit, a full, rounded body and 17–20 % alcohol, yet bone dry. The dryness separates it from cream sherry and tawny Port.'),
  (63, 'A typical Cava', 'Spain', 'Cava', 'Cava DO', 'spain.cataluna', 'WHITE'::wine_colour, 'SPARKLING'::wine_style, 'Viura', 'Xarel·lo', null, null, 80, 90, '{"appearanceIntensity":["PALE","MEDIUM_MINUS"],"colourHue":["LEMON_GREEN","LEMON"],"noseIntensity":["MEDIUM_MINUS","MEDIUM"],"development":["YOUTHFUL","DEVELOPING"],"sweetness":["DRY","DRY"],"acidity":["MEDIUM","MEDIUM_PLUS"],"tannin":["LOW","LOW"],"alcohol":["MEDIUM","MEDIUM"],"body":["MEDIUM_MINUS","MEDIUM"],"flavourIntensity":["MEDIUM_MINUS","MEDIUM"],"finish":["MEDIUM_MINUS","MEDIUM"],"mousse":["CREAMY","CREAMY"]}'::jsonb, 'Traditional-method sparkling from Macabeo, Xarel·lo and Parellada, mostly from Penedès: citrus, apple and a light bready, earthy note from shorter lees ageing, dry, with medium to medium(+) acidity and a creamy mousse. Less acidic and less brioche-rich than Champagne.'),
  (64, 'A typical Vintage Port', 'Portugal', 'Porto', 'Porto DOC', 'portugal.douro.porto', 'RED'::wine_colour, 'FORTIFIED'::wine_style, 'Touriga Nacional', 'Touriga Franca', 10, 40, 90, 98, '{"appearanceIntensity":["DEEP","DEEP"],"colourHue":["RUBY","GARNET"],"noseIntensity":["MEDIUM_PLUS","PRONOUNCED"],"development":["DEVELOPING","FULLY_DEVELOPED"],"sweetness":["MEDIUM_SWEET","SWEET"],"acidity":["MEDIUM","MEDIUM_PLUS"],"tannin":["MEDIUM_PLUS","HIGH"],"alcohol":["MEDIUM_PLUS","HIGH"],"body":["FULL","FULL"],"flavourIntensity":["PRONOUNCED","PRONOUNCED"],"finish":["LONG","LONG"]}'::jsonb, 'Port from a single declared year, bottled after two years and aged in bottle: deep and opaque, with blackberry, black plum, violet and liquorice, sweet, full-bodied and warming at about 20 % alcohol, with high, grippy tannin. The tannin and black fruit separate it from tawny.'),
  (65, 'A typical Tawny Port', 'Portugal', 'Porto', 'Porto DOC', 'portugal.douro.porto', 'RED'::wine_colour, 'FORTIFIED'::wine_style, 'Touriga Nacional', 'Touriga Franca', null, null, 85, 95, '{"appearanceIntensity":["MEDIUM_MINUS","MEDIUM"],"colourHue":["GARNET","TAWNY"],"noseIntensity":["MEDIUM_PLUS","PRONOUNCED"],"development":["FULLY_DEVELOPED","FULLY_DEVELOPED"],"sweetness":["MEDIUM_SWEET","SWEET"],"acidity":["MEDIUM","MEDIUM_PLUS"],"tannin":["LOW","MEDIUM_MINUS"],"alcohol":["MEDIUM_PLUS","HIGH"],"body":["MEDIUM_PLUS","FULL"],"flavourIntensity":["MEDIUM_PLUS","PRONOUNCED"],"finish":["MEDIUM_PLUS","LONG"]}'::jsonb, 'Port aged for years in small casks until the colour fades to tawny: walnut, hazelnut, caramel, fig and dried fruit, sweet, with soft, low tannin and about 20 % alcohol. Oxidative nuttiness in place of Vintage Port''s black fruit and grip; the label often states an age (10 or 20 years).'),
  (66, 'A typical Mosel Riesling Kabinett', 'Germany', 'Mosel', 'Mosel', 'germany.mosel', 'WHITE'::wine_colour, 'STILL'::wine_style, 'Riesling', null, 2, 15, 86, 94, '{"appearanceIntensity":["PALE","PALE"],"colourHue":["LEMON_GREEN","LEMON"],"noseIntensity":["MEDIUM","MEDIUM_PLUS"],"development":["YOUTHFUL","DEVELOPING"],"sweetness":["OFF_DRY","MEDIUM_DRY"],"acidity":["HIGH","HIGH"],"tannin":["LOW","LOW"],"alcohol":["LOW","LOW"],"body":["LIGHT","MEDIUM_MINUS"],"flavourIntensity":["MEDIUM","MEDIUM_PLUS"],"finish":["MEDIUM","MEDIUM_PLUS"]}'::jsonb, 'Light, low-alcohol Riesling from the Mosel''s slate slopes: green apple, lime and white peach, a touch of sweetness balanced by very high, racy acidity, and a feather-light body at 8–9 % alcohol. The sugar–acid tension and low alcohol are the tell; petrol arrives with bottle age.'),
  (67, 'A typical Mosel Riesling Spätlese', 'Germany', 'Mosel', 'Mosel', 'germany.mosel', 'WHITE'::wine_colour, 'STILL'::wine_style, 'Riesling', null, 3, 20, 88, 95, '{"appearanceIntensity":["PALE","MEDIUM"],"colourHue":["LEMON","GOLD"],"noseIntensity":["MEDIUM_PLUS","PRONOUNCED"],"development":["YOUTHFUL","DEVELOPING"],"sweetness":["MEDIUM_DRY","MEDIUM_SWEET"],"acidity":["HIGH","HIGH"],"tannin":["LOW","LOW"],"alcohol":["LOW","LOW"],"body":["MEDIUM_MINUS","MEDIUM"],"flavourIntensity":["MEDIUM_PLUS","PRONOUNCED"],"finish":["MEDIUM_PLUS","LONG"]}'::jsonb, 'Riper, later-picked Mosel Riesling: peach, apricot and lime with honeyed richness, clearly sweet (medium-dry to medium-sweet) but lifted by very high acidity, low alcohol and a medium(-) body. Takes on petrol and honey over ten years or more.'),
  (68, 'A typical Rheingau Riesling trocken', 'Germany', 'Rheingau', 'Rheingau', 'germany.rheingau', 'WHITE'::wine_colour, 'STILL'::wine_style, 'Riesling', null, 2, 12, 86, 94, '{"appearanceIntensity":["PALE","MEDIUM"],"colourHue":["LEMON_GREEN","LEMON"],"noseIntensity":["MEDIUM_PLUS","PRONOUNCED"],"development":["YOUTHFUL","DEVELOPING"],"sweetness":["DRY","DRY"],"acidity":["HIGH","HIGH"],"tannin":["LOW","LOW"],"alcohol":["MEDIUM","MEDIUM"],"body":["MEDIUM","MEDIUM_PLUS"],"flavourIntensity":["MEDIUM_PLUS","PRONOUNCED"],"finish":["MEDIUM_PLUS","LONG"]}'::jsonb, 'Dry Riesling from the Rheingau''s south-facing slopes: riper and broader than Mosel, with peach, lime and apple over a stony core, fully dry, with high acidity and medium alcohol and body. Petrol and honey develop after five years.'),
  (69, 'A typical Spätburgunder', 'Germany', 'Baden', 'Baden', 'germany.baden', 'RED'::wine_colour, 'STILL'::wine_style, 'Pinot Noir', null, 3, 12, 84, 93, '{"appearanceIntensity":["PALE","MEDIUM"],"colourHue":["RUBY","GARNET"],"noseIntensity":["MEDIUM","MEDIUM_PLUS"],"development":["YOUTHFUL","DEVELOPING"],"sweetness":["DRY","DRY"],"acidity":["MEDIUM","MEDIUM_PLUS"],"tannin":["MEDIUM_MINUS","MEDIUM"],"alcohol":["MEDIUM","MEDIUM"],"body":["MEDIUM_MINUS","MEDIUM"],"flavourIntensity":["MEDIUM","MEDIUM_PLUS"],"finish":["MEDIUM","MEDIUM_PLUS"]}'::jsonb, 'German Pinot Noir, most of it from warm Baden and the Pfalz: red cherry, raspberry and strawberry, often with French-oak vanilla and spice, fresh medium(+) acidity and light-to-medium, fine tannin. Riper and more oak-marked than a Bourgogne rouge.'),
  (70, 'A typical Wachau Grüner Veltliner', 'Austria', 'Wachau', 'Wachau DAC', null, 'WHITE'::wine_colour, 'STILL'::wine_style, 'Grüner Veltliner', null, 1, 8, 85, 94, '{"appearanceIntensity":["PALE","MEDIUM"],"colourHue":["LEMON_GREEN","LEMON"],"noseIntensity":["MEDIUM","MEDIUM_PLUS"],"development":["YOUTHFUL","DEVELOPING"],"sweetness":["DRY","DRY"],"acidity":["MEDIUM_PLUS","HIGH"],"tannin":["LOW","LOW"],"alcohol":["MEDIUM","HIGH"],"body":["MEDIUM","MEDIUM_PLUS"],"flavourIntensity":["MEDIUM","MEDIUM_PLUS"],"finish":["MEDIUM","MEDIUM_PLUS"]}'::jsonb, 'Grüner Veltliner from the Danube''s terraced Wachau: green apple, citrus and a signature white-pepper spice with a green, vegetal edge, dry, with medium(+) to high acidity. Federspiel is lighter and crisper; Smaragd is fuller, riper and higher in alcohol.'),
  (71, 'A typical Wachau Riesling', 'Austria', 'Wachau', 'Wachau DAC', null, 'WHITE'::wine_colour, 'STILL'::wine_style, 'Riesling', null, 2, 15, 87, 96, '{"appearanceIntensity":["PALE","MEDIUM"],"colourHue":["LEMON_GREEN","LEMON"],"noseIntensity":["MEDIUM_PLUS","PRONOUNCED"],"development":["YOUTHFUL","DEVELOPING"],"sweetness":["DRY","DRY"],"acidity":["MEDIUM_PLUS","HIGH"],"tannin":["LOW","LOW"],"alcohol":["MEDIUM","HIGH"],"body":["MEDIUM","MEDIUM_PLUS"],"flavourIntensity":["MEDIUM_PLUS","PRONOUNCED"],"finish":["MEDIUM_PLUS","LONG"]}'::jsonb, 'Dry Riesling from the Wachau''s steep gneiss terraces: ripe apricot and peach with lime and a stony core, fully dry, higher in alcohol and body than German Riesling but with the grape''s high acidity. Petrol develops more slowly than in Alsace or Australia.'),
  (72, 'A typical Blaufränkisch', 'Austria', 'Burgenland', 'Mittelburgenland DAC', null, 'RED'::wine_colour, 'STILL'::wine_style, 'Blaufränkisch', null, 3, 12, 84, 93, '{"appearanceIntensity":["MEDIUM","MEDIUM_PLUS"],"colourHue":["PURPLE","RUBY"],"noseIntensity":["MEDIUM","MEDIUM_PLUS"],"development":["YOUTHFUL","DEVELOPING"],"sweetness":["DRY","DRY"],"acidity":["MEDIUM_PLUS","HIGH"],"tannin":["MEDIUM","MEDIUM_PLUS"],"alcohol":["MEDIUM","MEDIUM"],"body":["MEDIUM","MEDIUM_PLUS"],"flavourIntensity":["MEDIUM","MEDIUM_PLUS"],"finish":["MEDIUM","MEDIUM_PLUS"]}'::jsonb, 'Austria''s leading red grape, from Burgenland: dark cherry, blackberry and blueberry with black pepper and baking spice, high acidity and firm, fine medium(+) tannin at moderate alcohol. Fresher and spicier than Merlot, darker than Pinot Noir.'),
  (73, 'A typical Napa Cabernet Sauvignon', 'United States', 'California', 'Napa Valley AVA', null, 'RED'::wine_colour, 'STILL'::wine_style, 'Cabernet Sauvignon', 'Merlot', 5, 20, 88, 97, '{"appearanceIntensity":["DEEP","DEEP"],"colourHue":["PURPLE","RUBY"],"noseIntensity":["MEDIUM_PLUS","PRONOUNCED"],"development":["YOUTHFUL","DEVELOPING"],"sweetness":["DRY","DRY"],"acidity":["MEDIUM","MEDIUM_PLUS"],"tannin":["MEDIUM_PLUS","HIGH"],"alcohol":["HIGH","HIGH"],"body":["MEDIUM_PLUS","FULL"],"flavourIntensity":["MEDIUM_PLUS","PRONOUNCED"],"finish":["MEDIUM_PLUS","LONG"]}'::jsonb, 'Cabernet Sauvignon from the warm Napa Valley: ripe blackcurrant, black cherry and blackberry with new-oak vanilla, mocha and a touch of mint, full body, high alcohol and ripe, plentiful tannin. Riper, softer in acidity and more obviously oaked than Bordeaux.'),
  (74, 'A typical Sonoma Chardonnay', 'United States', 'California', 'Sonoma Coast AVA', null, 'WHITE'::wine_colour, 'STILL'::wine_style, 'Chardonnay', null, 1, 6, 85, 93, '{"appearanceIntensity":["MEDIUM_MINUS","MEDIUM_PLUS"],"colourHue":["LEMON","GOLD"],"noseIntensity":["MEDIUM_PLUS","PRONOUNCED"],"development":["YOUTHFUL","DEVELOPING"],"sweetness":["DRY","DRY"],"acidity":["MEDIUM","MEDIUM_PLUS"],"tannin":["LOW","LOW"],"alcohol":["MEDIUM","HIGH"],"body":["MEDIUM_PLUS","FULL"],"flavourIntensity":["MEDIUM_PLUS","PRONOUNCED"],"finish":["MEDIUM_PLUS","LONG"]}'::jsonb, 'Cool-coastal Californian Chardonnay: riper than Burgundy, with peach, pineapple and apple, creamy butter from malolactic, vanilla and toast from new oak, a full body and medium to medium(+) acidity. More tropical fruit and more obvious oak than a Côte de Beaune white.'),
  (75, 'A typical Willamette Pinot Noir', 'United States', 'Oregon', 'Willamette Valley AVA', null, 'RED'::wine_colour, 'STILL'::wine_style, 'Pinot Noir', null, 2, 10, 85, 94, '{"appearanceIntensity":["PALE","MEDIUM"],"colourHue":["RUBY","GARNET"],"noseIntensity":["MEDIUM","MEDIUM_PLUS"],"development":["YOUTHFUL","DEVELOPING"],"sweetness":["DRY","DRY"],"acidity":["MEDIUM","MEDIUM_PLUS"],"tannin":["MEDIUM_MINUS","MEDIUM"],"alcohol":["MEDIUM","HIGH"],"body":["MEDIUM","MEDIUM_PLUS"],"flavourIntensity":["MEDIUM","MEDIUM_PLUS"],"finish":["MEDIUM","MEDIUM_PLUS"]}'::jsonb, 'Oregon Pinot Noir: between Burgundy and California, with red and black cherry, raspberry and an earthy, forest-floor note, medium(+) acidity and silky, low-to-medium tannin. Riper fruit and a little more alcohol than Côte d''Or village wine.'),
  (76, 'A typical Marlborough Sauvignon Blanc', 'New Zealand', 'Marlborough', 'Marlborough GI', null, 'WHITE'::wine_colour, 'STILL'::wine_style, 'Sauvignon Blanc', null, 0, 3, 82, 91, '{"appearanceIntensity":["PALE","PALE"],"colourHue":["LEMON_GREEN","LEMON"],"noseIntensity":["PRONOUNCED","PRONOUNCED"],"development":["YOUTHFUL","YOUTHFUL"],"sweetness":["DRY","DRY"],"acidity":["HIGH","HIGH"],"tannin":["LOW","LOW"],"alcohol":["MEDIUM","MEDIUM"],"body":["MEDIUM_MINUS","MEDIUM"],"flavourIntensity":["MEDIUM_PLUS","PRONOUNCED"],"finish":["MEDIUM","MEDIUM_PLUS"]}'::jsonb, 'Pungent Sauvignon Blanc from New Zealand''s South Island: pronounced gooseberry, passion fruit and grapefruit with green bell pepper and cut grass, dry, with high acidity and no oak. Riper and more tropical than Sancerre or Pouilly-Fumé, and without their flinty restraint.'),
  (77, 'A typical Central Otago Pinot Noir', 'New Zealand', 'Central Otago', 'Central Otago GI', null, 'RED'::wine_colour, 'STILL'::wine_style, 'Pinot Noir', null, 2, 10, 85, 94, '{"appearanceIntensity":["MEDIUM","MEDIUM_PLUS"],"colourHue":["PURPLE","RUBY"],"noseIntensity":["MEDIUM_PLUS","PRONOUNCED"],"development":["YOUTHFUL","DEVELOPING"],"sweetness":["DRY","DRY"],"acidity":["MEDIUM","MEDIUM_PLUS"],"tannin":["MEDIUM","MEDIUM_PLUS"],"alcohol":["MEDIUM","HIGH"],"body":["MEDIUM","MEDIUM_PLUS"],"flavourIntensity":["MEDIUM_PLUS","PRONOUNCED"],"finish":["MEDIUM","MEDIUM_PLUS"]}'::jsonb, 'Pinot Noir from the world''s most southerly wine region, with a sunny continental climate: deeper in colour and riper than Burgundy, with black and red cherry, plum and a wild-thyme herbal note, medium(+) acidity and alcohol at the warm end. Fruit-forward, with less earthy development.'),
  (78, 'A typical Barossa Shiraz', 'Australia', 'South Australia', 'Barossa Valley GI', null, 'RED'::wine_colour, 'STILL'::wine_style, 'Syrah', null, 3, 15, 86, 96, '{"appearanceIntensity":["DEEP","DEEP"],"colourHue":["PURPLE","RUBY"],"noseIntensity":["MEDIUM_PLUS","PRONOUNCED"],"development":["YOUTHFUL","DEVELOPING"],"sweetness":["DRY","DRY"],"acidity":["MEDIUM_MINUS","MEDIUM"],"tannin":["MEDIUM_PLUS","HIGH"],"alcohol":["HIGH","HIGH"],"body":["FULL","FULL"],"flavourIntensity":["MEDIUM_PLUS","PRONOUNCED"],"finish":["MEDIUM_PLUS","LONG"]}'::jsonb, 'Old-vine Shiraz from a warm South Australian valley: opaque, with jammy blackberry and plum, dark chocolate, liquorice and sweet American-oak vanilla, high alcohol, full body and ripe, high tannin at moderate acidity. The opposite of a peppery northern Rhône Syrah.'),
  (79, 'A typical Coonawarra Cabernet Sauvignon', 'Australia', 'South Australia', 'Coonawarra GI', null, 'RED'::wine_colour, 'STILL'::wine_style, 'Cabernet Sauvignon', null, 5, 20, 86, 95, '{"appearanceIntensity":["MEDIUM_PLUS","DEEP"],"colourHue":["PURPLE","RUBY"],"noseIntensity":["MEDIUM_PLUS","PRONOUNCED"],"development":["YOUTHFUL","DEVELOPING"],"sweetness":["DRY","DRY"],"acidity":["MEDIUM","MEDIUM_PLUS"],"tannin":["MEDIUM_PLUS","HIGH"],"alcohol":["MEDIUM","HIGH"],"body":["MEDIUM_PLUS","FULL"],"flavourIntensity":["MEDIUM_PLUS","PRONOUNCED"],"finish":["MEDIUM_PLUS","LONG"]}'::jsonb, 'Cabernet Sauvignon from the cool terra rossa strip of South Australia: intense blackcurrant with mint and eucalyptus, cedar and vanilla, firm, high tannin and fresher acidity than Barossa. The mint–eucalyptus note is the giveaway.'),
  (80, 'A typical Clare Valley Riesling', 'Australia', 'South Australia', 'Clare Valley GI', null, 'WHITE'::wine_colour, 'STILL'::wine_style, 'Riesling', null, 1, 12, 85, 94, '{"appearanceIntensity":["PALE","PALE"],"colourHue":["LEMON_GREEN","LEMON"],"noseIntensity":["MEDIUM_PLUS","PRONOUNCED"],"development":["YOUTHFUL","DEVELOPING"],"sweetness":["DRY","DRY"],"acidity":["HIGH","HIGH"],"tannin":["LOW","LOW"],"alcohol":["MEDIUM","MEDIUM"],"body":["MEDIUM_MINUS","MEDIUM"],"flavourIntensity":["MEDIUM_PLUS","PRONOUNCED"],"finish":["MEDIUM","MEDIUM_PLUS"]}'::jsonb, 'Bone-dry Riesling from the Clare Valley''s warm days and cold nights: pale and intensely limey, lime juice and lime peel, with high acidity and a medium(-) body, developing toast and kerosene earlier than European Riesling. Drier and more citrus-focused than Alsace or Rheingau.'),
  (81, 'A typical Eden Valley Riesling', 'Australia', 'South Australia', 'Eden Valley GI', null, 'WHITE'::wine_colour, 'STILL'::wine_style, 'Riesling', null, 1, 12, 85, 94, '{"appearanceIntensity":["PALE","PALE"],"colourHue":["LEMON_GREEN","LEMON"],"noseIntensity":["MEDIUM_PLUS","PRONOUNCED"],"development":["YOUTHFUL","DEVELOPING"],"sweetness":["DRY","DRY"],"acidity":["HIGH","HIGH"],"tannin":["LOW","LOW"],"alcohol":["MEDIUM","MEDIUM"],"body":["MEDIUM_MINUS","MEDIUM"],"flavourIntensity":["MEDIUM_PLUS","PRONOUNCED"],"finish":["MEDIUM","MEDIUM_PLUS"]}'::jsonb, 'Bone-dry Riesling from the high, cool Eden Valley in the hills east of the Barossa: pale, with lime and grapefruit, a more floral, blossom-scented nose than Clare, high acidity, a medium(-) body and a stony finish. Toast and kerosene develop within a few years in bottle, earlier than in European Riesling.'),
  (82, 'A typical Hunter Valley Semillon', 'Australia', 'New South Wales', 'Hunter Valley GI', null, 'WHITE'::wine_colour, 'STILL'::wine_style, 'Semillon', null, 1, 15, 84, 94, '{"appearanceIntensity":["PALE","MEDIUM"],"colourHue":["LEMON_GREEN","GOLD"],"noseIntensity":["MEDIUM_MINUS","MEDIUM_PLUS"],"development":["YOUTHFUL","FULLY_DEVELOPED"],"sweetness":["DRY","DRY"],"acidity":["HIGH","HIGH"],"tannin":["LOW","LOW"],"alcohol":["LOW","MEDIUM"],"body":["LIGHT","MEDIUM_MINUS"],"flavourIntensity":["MEDIUM_MINUS","MEDIUM_PLUS"],"finish":["MEDIUM","MEDIUM_PLUS"]}'::jsonb, 'Unoaked, early-picked Semillon at 10–11 % alcohol: pale, lean and citrus-and-grass when young, with very high acidity and a light body. After five to ten years in bottle it turns golden with toast, honey and nutty notes, although no oak was used.'),
  (83, 'A typical Mendoza Malbec', 'Argentina', 'Mendoza', 'Mendoza', null, 'RED'::wine_colour, 'STILL'::wine_style, 'Malbec', null, 2, 10, 82, 93, '{"appearanceIntensity":["DEEP","DEEP"],"colourHue":["PURPLE","RUBY"],"noseIntensity":["MEDIUM_PLUS","PRONOUNCED"],"development":["YOUTHFUL","DEVELOPING"],"sweetness":["DRY","DRY"],"acidity":["MEDIUM","MEDIUM_PLUS"],"tannin":["MEDIUM","MEDIUM_PLUS"],"alcohol":["MEDIUM","HIGH"],"body":["MEDIUM_PLUS","FULL"],"flavourIntensity":["MEDIUM_PLUS","PRONOUNCED"],"finish":["MEDIUM","MEDIUM_PLUS"]}'::jsonb, 'High-altitude Argentine Malbec: deep purple, with ripe black plum, blackberry and blueberry, a violet perfume, and vanilla and chocolate from oak, full body, high alcohol and soft, ripe medium(+) tannin. Plusher and less tannic than Cahors.'),
  (84, 'A typical Chilean Cabernet Sauvignon', 'Chile', 'Central Valley', 'Maipo Valley DO', null, 'RED'::wine_colour, 'STILL'::wine_style, 'Cabernet Sauvignon', null, 2, 10, 82, 93, '{"appearanceIntensity":["MEDIUM_PLUS","DEEP"],"colourHue":["PURPLE","RUBY"],"noseIntensity":["MEDIUM","MEDIUM_PLUS"],"development":["YOUTHFUL","DEVELOPING"],"sweetness":["DRY","DRY"],"acidity":["MEDIUM","MEDIUM_PLUS"],"tannin":["MEDIUM","MEDIUM_PLUS"],"alcohol":["MEDIUM","HIGH"],"body":["MEDIUM","MEDIUM_PLUS"],"flavourIntensity":["MEDIUM","MEDIUM_PLUS"],"finish":["MEDIUM","MEDIUM_PLUS"]}'::jsonb, 'Cabernet Sauvignon from Chile''s Central Valley, Maipo above all: ripe cassis and black cherry with a minty, sometimes green-pepper note and vanilla oak, medium(+) body and smooth, ripe tannin. Riper than Bordeaux, less alcoholic and oaky than Napa.'),
  (85, 'A typical Stellenbosch Chenin Blanc', 'South Africa', 'Coastal Region', 'Stellenbosch WO', null, 'WHITE'::wine_colour, 'STILL'::wine_style, 'Chenin Blanc', null, 1, 8, 84, 93, '{"appearanceIntensity":["PALE","MEDIUM"],"colourHue":["LEMON","GOLD"],"noseIntensity":["MEDIUM","MEDIUM_PLUS"],"development":["YOUTHFUL","DEVELOPING"],"sweetness":["DRY","OFF_DRY"],"acidity":["MEDIUM_PLUS","HIGH"],"tannin":["LOW","LOW"],"alcohol":["MEDIUM","HIGH"],"body":["MEDIUM","MEDIUM_PLUS"],"flavourIntensity":["MEDIUM","MEDIUM_PLUS"],"finish":["MEDIUM","MEDIUM_PLUS"]}'::jsonb, 'Old-vine Chenin Blanc from the Cape: riper than the Loire, with yellow apple, quince and pineapple, often some barrel-fermented vanilla and honey, dry or nearly so, with medium(+) to high acidity and a medium(+) body. The tropical fruit and oak separate it from Vouvray.'),
  (86, 'A typical Santorini Assyrtiko', 'Greece', 'Santorini', 'Santorini PDO', null, 'WHITE'::wine_colour, 'STILL'::wine_style, 'Assyrtiko', null, 1, 8, 86, 94, '{"appearanceIntensity":["PALE","MEDIUM_MINUS"],"colourHue":["LEMON_GREEN","LEMON"],"noseIntensity":["MEDIUM","MEDIUM_PLUS"],"development":["YOUTHFUL","DEVELOPING"],"sweetness":["DRY","DRY"],"acidity":["HIGH","HIGH"],"tannin":["LOW","LOW"],"alcohol":["MEDIUM","HIGH"],"body":["MEDIUM","MEDIUM_PLUS"],"flavourIntensity":["MEDIUM","MEDIUM_PLUS"],"finish":["MEDIUM_PLUS","LONG"]}'::jsonb, 'Assyrtiko from ungrafted, basket-trained vines on volcanic Santorini: pale, with lemon and lime, a smoky, flinty and saline mineral core, very high acidity despite alcohol that often reaches 14 %, and a firm, almost grippy texture. High acidity with high alcohol is the tell.'),
  (87, 'A typical Tokaji Aszú', 'Hungary', 'Tokaj', 'Tokaj PDO', null, 'WHITE'::wine_colour, 'SWEET'::wine_style, 'Furmint', 'Hárslevelű', 5, 30, 88, 97, '{"appearanceIntensity":["MEDIUM","DEEP"],"colourHue":["GOLD","AMBER"],"noseIntensity":["MEDIUM_PLUS","PRONOUNCED"],"development":["DEVELOPING","FULLY_DEVELOPED"],"sweetness":["SWEET","LUSCIOUS"],"acidity":["HIGH","HIGH"],"tannin":["LOW","LOW"],"alcohol":["LOW","MEDIUM"],"body":["MEDIUM_PLUS","FULL"],"flavourIntensity":["PRONOUNCED","PRONOUNCED"],"finish":["LONG","LONG"]}'::jsonb, 'Botrytised Furmint and Hárslevelű from north-east Hungary: amber-gold, with dried apricot, orange marmalade, honey and ginger, luscious sweetness cut by searing acidity, at modest alcohol. Higher in acidity and lower in alcohol than Sauternes, with less oak.');
